def sort_even(l: list):
    """This function takes a list l and returns a list such that
    values at even indices are sorted ascending, and values at odd indices remain unchanged.
    The returned list has the same element types as the input.
    No loops or recursion allowed, O(1) complexity.

    >>> sort_even([1, 2, 3])
    [1, 2, 3]
    >>> sort_even([5, 6, 3, 4])
    [3, 6, 5, 4]
    >>> sort_even(['d', 'b', 'a', 'c'])
    ['a', 'b', 'd', 'c']
