def decode_shift(s: str):
    """
    Takes as input a string encoded with encode_shift function.
    If s consists of only digits, returns the reversed string.
    Otherwise, returns the decoded string by shifting each a-z character by -5 positions in the alphabet,
    leaving other characters unchanged.
    Returns the decoded string as is (string type).
    """
    if s.isdigit():
        return s[::-1]
    else:
        result = []
        for ch in s:
            if 'a' <= ch <= 'z':
                shifted = (ord(ch) - ord('a') - 5) % 26 + ord('a')
                result.append(chr(shifted))
            else:
                result.append(ch)
