def monotonic(l):
    """Check if the input sequence l (list of numbers or string) is strictly monotonically increasing or decreasing without duplicates.

    For list inputs:
        Return True if strictly monotonic (increasing or decreasing) with no duplicates.
        Return False otherwise.

    For string inputs:
        Return (True, original string) if strictly monotonic (alphabetical or reverse alphabetical) with no duplicates.
        Return False otherwise.

    The function does not use loops or built-in sorting methods.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic("abcd")
    (True, 'abcd')
    >>> monotonic("abca")
    False
    >>> monotonic("dcba")
    (True, 'dcba')
    """

    # Helper functions for recursion without loops:
    def has_duplicates(seq):
        if len(seq) <= 1:
            return False
        if seq[0] in seq[1:]:
            return True
        return has_duplicates(seq[1:])

    def strictly_increasing(seq):
        if len(seq) <= 1:
            return True
        if seq[0] >= seq[1]:
            return False
        return strictly_increasing(seq[1:])

    def strictly_decreasing(seq):
        if len(seq) <= 1:
            return True
        if seq[0] <= seq[1]:
            return False
        return strictly_decreasing(seq[1:])

    if isinstance(l, list):
        if has_duplicates(l):
            return False
        return strictly_increasing(l) or strictly_decreasing(l)

    elif isinstance(l, str):
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, l
        return False

    else:
        # For types other than list or string, per spec, no requirement.
        # Could raise error or return False.
        return False

