def circular_shift(x, shift):
    """Circular shift the digits of the integer or digit string x, shifting the digits right by shift positions.
    If shift > number of digits, return the digits reversed as a string.
    Return only the resulting string.

    The function does not use loops and runs in O(1).

    >>> circular_shift(12, 1)
    '21'
    >>> circular_shift(12, 2)
    '12'
    >>> circular_shift('1234', 5)
    '4321'
    """
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift %= n
    return s[-shift:] + s[:-shift]

