def anti_shuffle(s):
    """
    Takes a string s and returns a string where each word's characters are sorted
    in ascending ASCII order. Words are sequences of non-space characters.
    All spaces (including multiple consecutive spaces) are preserved exactly.
    The order of words and spaces in the string is preserved.

    Args:
        s (str): input string

    Returns:
        str: transformed string with each word's chars sorted ascending ASCII
    """
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            # preserve spaces as is
            start = i
            while i < n and s[i] == ' ':
                i += 1
            result.append(s[start:i])
        else:
            # extract a word
            start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)

