def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Helper to check if an array is sorted non-decreasingly
    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Check if already sorted
    if is_sorted(arr):
        return True

    # We can perform up to n right shifts and check each time
    # But without loops -> we use recursion

    def try_shift(a, shifts_left, shifts_done=0):
        if shifts_left == 0:
            return False
        # perform one right shift
        shifted = [a[-1]] + a[:-1]
        if is_sorted(shifted):
            return True
        return try_shift(shifted, shifts_left-1, shifts_done+1)

    return try_shift(arr, n)

