def max_fill(grid, capacity):
    import math
    # Count water units in each well (row)
    water_counts = list(map(sum, grid))
    # Sort wells by ascending water count, maintaining original order on ties
    # Python's sort is stable, so we can use sorted with key=water_counts via enumerate
    sorted_wells = sorted(enumerate(water_counts), key=lambda x: x[1])
    # Compute total lowers: sum of ceil(water / capacity) for each well
    total_lowers = sum(math.ceil(count / capacity) for _, count in sorted_wells)
    # Return as integer (not as string)
    return total_lowers

