def maximum(arr, k):
    """
    Given an array arr of comparable elements and a non-negative integer k ≤ len(arr),
    return a list of length k with the maximum k elements from arr (including duplicates),
    sorted in ascending order by value, ignoring the original order of elements.

    Parameters:
        arr (list): List of comparable elements (ints, strings, etc.)
        k (int): Number of maximum elements to return, 0 <= k <= len(arr)

    Returns:
        list: Sorted list of the maximum k elements in ascending order.
    """
    if k == 0:
        return []

    # Find max k elements without using built-in sort
    # Since built-in sorting is not allowed, implement a simple selection algorithm.
    # However, the time complexity cannot be O(1) (constant) for sorting or selecting k elements.
    # But we must respect the clarification and original requirement as much as possible.
    #
    # We'll do a simple approach:
    # - Create a copy of the array
    # - Repeatedly find the maximum element, remove it, and add to a result list
    # - Then reverse the result to get ascending order
    #
    # This is O(k * n), which is acceptable given constraints (n ≤ 1000).

    arr_copy = arr[:]  # copy to not modify original

    max_elements = []
    for _ in range(k):
        # find the max element in arr_copy
        max_elem = arr_copy[0]
        for elem in arr_copy[1:]:
            if elem > max_elem:
                max_elem = elem
        max_elements.append(max_elem)
        arr_copy.remove(max_elem)  # remove first occurrence

    # sort max_elements in ascending order without built-in sort
    # simple bubble sort (since k ≤ n ≤ 1000, it's acceptable)
    for i in range(k):
        for j in range(0, k - i - 1):
            if max_elements[j] > max_elements[j + 1]:
                max_elements[j], max_elements[j + 1] = max_elements[j + 1], max_elements[j]

    return max_elements

