def digits(n, s=None):
    """
    Given a positive integer n (int or str), return the product of the odd digits as a string
    and the product of even digits as an integer. The function works without loops or iteration.

    Rules (based on original requirement + user's clarification):
    - If input n is int:
      - If all digits are even and only one even digit: return string "0"
      - If all digits are even and multiple even digits: return int 0
      - If all digits are odd: return the product of odd digits as int
      - If mixed digits: return the product of odd digits as int
    - If input n is str:
      - If all digits even (any count): return int 0
      - If all digits odd or mixed: return the product of odd digits as string

    Complexity O(1) means no loops; use recursion or fixed-length handling (assuming input length is limited).

    Examples:
    digits(1)  == 1
    digits(4)  == "0"
    digits(235) == 15
    digits("235") == "15"
    digits(246) == 0
    digits("246") == 0
    """

    # Convert n to string for uniform digit access
    s_n = str(n)

    # Count digits (length)
    length = len(s_n)

    # Extract digits as int list (for arithmetic)
    digits_list = list(map(int, s_n))

    # Helper to compute product of digits (without loops): recursion

    def prod(lst):
        if not lst:
            return 1
        return lst[0] * prod(lst[1:])

    # Determine odd digits and even digits lists
    odd_digits = [d for d in digits_list if d % 2 == 1]
    even_digits = [d for d in digits_list if d % 2 == 0]

    all_even = (len(odd_digits) == 0)
    all_odd = (len(even_digits) == 0)

    # Compute product of odd digits
    product_odd = prod(odd_digits) if odd_digits else None
    # Compute product of even digits
    product_even = prod(even_digits) if even_digits else None

    # Determine input type
    is_str_input = isinstance(n, str)
    is_int_input = isinstance(n, int)

    # According to requirements:

    if all_even:
        # All even digits
        if is_int_input:
            # If single even digit, return string "0"
            if length == 1:
                return "0"
            else:
                return 0
        else:
            # str input with all even digits returns 0 (int)
            return 0

    if all_odd:
        # All odd digits
        if is_str_input:
            # Return product as string
            return str(product_odd)
        else:
            # int input returns product as int
            return product_odd

    # Mixed digits (some odd some even)
    # Return product of odd digits, type depends on input
    if is_str_input:
        return str(product_odd)
    else:
        return product_odd

