def sum_squares(lst):
    def ceil_num(num):
        int_part = int(num)
        # If num is already an integer or num <= int_part (for negative floats), return int_part
        # Otherwise, return int_part + 1
        if num == int_part or num < int_part:
            return int_part
        else:
            return int_part + 1

    def helper(index):
        if index == len(lst):
            return 0
        c = ceil_num(lst[index])
        return c * c + helper(index + 1)

    return helper(0)

