def order_by_points(nums):
    """
    Sort the given list of integers or strings representing numbers
    by the sum of their digits, where for negative numbers the sign affects
    only the first digit's value in the sum. Preserve original order on ties.
    Return the sorted list (not a string).

    If the input list is empty, return an empty list.

    No loops or recursion are used.
    """

    def digit_sum(x):
        s = str(x)
        if s.startswith('-'):
            # negative number: subtract first digit, add the rest
            first_digit = int(s[1])
            rest = s[2:]
            # sum digits in rest
            rest_sum = sum(map(int, rest)) if rest else 0
            return -first_digit + rest_sum
        else:
            # positive number: sum digits
            return sum(map(int, s))

    # Use sorted with stable sort (default) and key digit_sum
    return sorted(nums, key=digit_sum)

