from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string containing multiple groups of parentheses separated by any non-parenthesis characters,
    for each group of consecutive parentheses:
      - return the maximum nesting depth if the parentheses are balanced,
      - otherwise return 0,
      - empty groups yield 0.
    Return a list of integers corresponding to each group in input order.

    Example:
      parse_nested_parens('(())a(()())b()') == [2, 2, 1]
    """
    results = []
    group = []

    def max_depth_balance(s: str) -> int:
        depth = 0
        max_depth = 0
        for ch in s:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
                if depth < 0:
                    return 0  # unbalanced
        return max_depth if depth == 0 else 0

    for ch in paren_string:
        if ch in '()':
            group.append(ch)
        else:
            if group:
                depth = max_depth_balance(''.join(group))
                results.append(depth)
                group = []
            else:
                # no current group, skip separator
                pass

    # handle last group if any
    if group:
        depth = max_depth_balance(''.join(group))
        results.append(depth)

    return results

