def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.

    Positive shift rotates digits right, negative shift rotates digits left.
    Leading zeros resulting from the shift are preserved.
    """
    s = str(x)
    n = len(s)
    if n == 0:
        return s  # empty string edge case

    # Normalize shift to range [0, n-1]
    shift = shift % n

    # Right shift by shift positions
    if shift == 0:
