def select_words(s, n):
    """
    Given a string s and a natural number n, return a list of all words from s
    that contain at least n distinct letters.

    Words are sequences separated by whitespace.
    The returned list preserves the original order of the words in s.

    For example:
    select_words('a aa aaa aaaa', 1) -> ['a', 'aa', 'aaa', 'aaaa']
    select_words('a aa aaa aaaa', 2) -> []
    select_words('abc bca cab xyz', 3) -> ['abc', 'bca', 'cab', 'xyz']
    select_words('apple ape april', 4) -> ['apple', 'april']
    """
    words = s.split()
    selected = []
    for word in words:
        distinct_letters = set(word)
        if len(distinct_letters) >= n:
            selected.append(word)
    return selected

