def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing (non-strict).
    An empty list or a single-element list is considered monotonic.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 1, 2, 2])
