def sum_squares(lst):
    """
    This function takes a list of integers. For each entry:
    - if its index is a multiple of 3, square the entry,
    - else if its index is a multiple of 4 and not a multiple of 3, cube the entry,
    - else leave the entry unchanged.
    It then returns the sum of all transformed entries.

    Examples:
    For lst = [1, 2, 3], the output should be 6
    For lst = [], the output should be 0
    For lst = [-1, -5, 2, -1, -5], the output should be -126
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

