def fizz_buzz(n: int) -> int:
    """
    Return the number of times the digit '7' appears in positive integers less than n
    which are divisible by 11 or 13.

    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
