def monotonic(l: list) -> bool:
    """
    Return True if list elements are monotonically non-decreasing or non-increasing.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
