def circular_shift(x, shift):
    """
    Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed as a string.

    >>> circular_shift(12, 1)
    '21'
    >>> circular_shift(12, 2)
    '12'
    >>> circular_shift(100, 1)
    '010'
    >>> circular_shift(12, 3)  # shift > number of digits, return reversed
    '21'
    """
    digits = str(x)
    n = len(digits)
    if shift > n:
        return digits[::-1]
    shift = shift % n
    if shift == 0:
        return digits
    return digits[-shift:] + digits[:-shift]

