def anti_shuffle(s):
    """
    Takes a string s and returns a new string where each token separated by space 
    is replaced by the token with its characters sorted ascending by ASCII value.
    Spaces are preserved exactly in their original order and count.

    Tokens are defined by splitting on spaces only.
    Other whitespace characters (like tabs or newlines) are part of tokens and sorted.

    Examples:
    anti_shuffle('Hi') -> 'Hi'
    anti_shuffle('hello') -> 'ehllo'
    anti_shuffle('Hello World!!!') -> 'Hello !!!Wdlor'
    """
    parts = s.split(' ')
    sorted_parts = [''.join(sorted(part)) for part in parts]
    return ' '.join(sorted_parts)

