def move_one_ball(arr):
    """
    Determine if the given array can be right-shifted any number of times to become sorted in non-decreasing order.

    Parameters:
    arr (list of int): The input array of unique integers.

    Returns:
    bool: True if the array is empty or can be right-shifted to become sorted non-decreasingly, False otherwise.
    """
    if not arr:
        return True

    count_breaks = 0
    n = len(arr)

    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            count_breaks += 1
            if count_breaks > 1:
                return False
    return True

