def select_words(s, n):
    """
    Given a string s and a natural number n, return a list of all words from string s
    that contain exactly n consonants, in the order these words appear in s.
    If s is empty, return an empty list.

    Words contain only letters and spaces. Consonants are letters that are alphabetic
    and not vowels (a, e, i, o, u), counted case-insensitively.

    Examples:
    select_words("Mary had a little lamb", 4) ==> ["little"]
    select_words("Mary had a little lamb", 3) ==> ["Mary", "lamb"]
    select_words("simple white space", 2) ==> []
    select_words("Hello world", 4) ==> ["world"]
    select_words("Uncle sam", 3) ==> ["Uncle"]
    """
    vowels = set('aeiouAEIOU')
    if not s:
        return []

    words = s.split()
    result = []
    for word in words:
        consonant_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result

