def sum_squares(lst):
    """
    This function takes a list of integers. For each element:
    - if its index is a multiple of 3, square the element;
    - else if its index is a multiple of 4, cube the element;
    - otherwise, leave it unchanged.
    Then returns the sum of all processed elements.

    Examples:
    sum_squares([1,2,3]) -> 14
    sum_squares([]) -> 0
    sum_squares([-1,-5,2,-1,-5]) -> 4
    sum_squares([0,1,2,3,4]) -> 28
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

