from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """ 
    Takes a string containing multiple groups of parentheses separated by whitespace.
    For each group, computes the maximum depth of nested parentheses by counting '(' and ')'
    without validating correctness.

    Example:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    results = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

