def fizz_buzz(n: int) -> int:
    """
    Return the number of times the digit '7' appears in integers i where 0 <= i < n,
    and i is divisible by 11 or 13.

    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    >>> fizz_buzz(12)
