def monotonic(l: list) -> bool:
    """
    Return True if the list is monotonic (entirely non-decreasing or entirely non-increasing), False otherwise.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    >>> monotonic([3, 3, 2, 2])
    True
    >>> monotonic([1])
    True
    >>> monotonic([])
    True
    """
    if not l:
        return True

