def smallest_change(arr):
    """
    Given an array arr of integers, find the minimal number of single-element changes
    needed to make the array palindromic. Each differing pair (arr[i], arr[n-1-i])
    requires exactly one change.

    Args:
        arr (list of int): The input array.

    Returns:
        int: The minimal number of changes to make arr palindromic.
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count

