def anti_shuffle(s):
    """
    Write a function that takes a string and returns an ordered version of it.
    Ordered version of string, is a string where all words (separated by space)
    are replaced by a new word where all the characters arranged in
    descending or ascending order based on ascii value.
    Note: You should keep the order of words and blank spaces in the sentence.

    For example:
    anti_shuffle('Hi') returns 'Hi'
    anti_shuffle('hello') returns 'ehllo'
    anti_shuffle('Hello World!!!') returns 'Hello !!!Wdlor'
    """

    # Split the string by spaces to preserve the number of words and spaces
    # but keep the exact spacing by splitting on spaces and joining back by spaces.
    parts = s.split(' ')
    result_parts = []

    for word in parts:
        if not word:
            # preserve empty parts (multiple spaces)
            result_parts.append(word)
            continue

        # Determine sort order: if word is all alphabetic, ascending; else descending
        if word.isalpha():
            sorted_word = ''.join(sorted(word))
        else:
            sorted_word = ''.join(sorted(word, reverse=True))

        result_parts.append(sorted_word)

    # Join with spaces to preserve original spacing
    return ' '.join(result_parts)

