def sum_squares(lst):
    """
    This function will take a list of integers. For all entries in the list:
    - if the index is a multiple of 3, the integer entry is squared,
    - else if the index is a multiple of 4 (and not a multiple of 3), the integer entry is cubed,
    - otherwise, the integer entry is unchanged.
    The function then returns the sum of all transformed entries.

    Examples:
    sum_squares([1,2,3]) -> 6
    sum_squares([]) -> 0
    sum_squares([-1,-5,2,-1,-5]) -> -126
    sum_squares([1, 2, 3, 4, 5]) -> 95
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

