def order_by_points(nums):
    """
    Sort the list of integers based on the sum of their digits considering sign.
    That is, for each number, sum the digits with the sign of the number applied to each digit.
    For example:
      - For 11: sum is 1 + 1 = 2
      - For -11: sum is -1 + -1 = -2
    Sort the list in ascending order based on these sums.
    If sums are equal, maintain the original order (stable sort).

    Examples:
    >>> order_by_points([1, 11, -1, -11, -12])
    [-1, -11, 1, -12, 11]
    >>> order_by_points([])
    []
    >>> order_by_points([10, 2, 20, 11])
    [10, 2, 20, 11]
    """
    def sum_signed_digits(n):
        sign = -1 if n < 0 else 1
        return sign * sum(int(d) for d in str(abs(n)))

    # Use stable sort, sorting by sum of signed digits ascending
    return sorted(nums, key=lambda x: sum_signed_digits(x))

