def below_zero(ops):
    records = []
    for op in ops:
        if op == 'C':
            if records:
                records.pop()
        elif op == 'D':
            if records:
                records.append(2 * records[-1])
        elif op == '+':
            if len(records) >= 2:
                records.append(records[-1] + records[-2])
        else:
            # try to parse as integer
            try:
                num = int(op)
                records.append(num)
            except ValueError:
                # ignore invalid operation
                pass
    return sum(records) < 0

