def sort_even(lst):
    # Extract elements at even indices (0-based) and sort them ascending
    even_index_elements = [lst[i] for i in range(0, len(lst), 2)]
    even_index_elements.sort()

    # Create a copy to avoid modifying the original list directly
    result = lst[:]

    # Replace elements at even indices with sorted values
    for i, val in zip(range(0, len(lst), 2), even_index_elements):
        result[i] = val

    return result

