def monotonic(nums):
    """
    Check if the list nums is monotonic: entirely non-increasing or non-decreasing.
    Adjacent equal elements are allowed.

    Parameters:
    nums (list of numbers): The sequence to check.

    Returns:
    bool: True if nums is monotonic, False otherwise.
    """
    if not nums:
        return True  # An empty list can be considered monotonic

    non_decreasing = True
    non_increasing = True

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            non_increasing = False
        elif nums[i] < nums[i - 1]:
            non_decreasing = False

        # Early exit if both are False
        if not non_decreasing and not non_increasing:
            return False

    return True

