def circular_shift(x: int, y: int) -> str:
    s = str(x)
    n = len(s)
    if y >= n:
        # If y is greater than or equal to the number of digits in x,
        # return the original string (no shift).
        return s
    # Perform a right circular shift by y positions:
    # Take the last y digits and put them in front.
    return s[-y:] + s[:-y]

