def will_it_fly(q, w):
    # If q is a dict or has 'ok' and 'weight' attributes
    if isinstance(q, dict):
        ok = q.get('ok')
        weight = q.get('weight')
        # Check that weight is a number
        if ok and isinstance(weight, (int, float)) and weight <= w:
            return True
        return False

    # Otherwise, if q is a sequence of numbers (list, tuple, etc.)
    # Check if all elements are numeric
    try:
        # Convert to list to handle any sequence
        elements = list(q)
    except TypeError:
        return False

    if not elements:
        # Empty sequence is considered palindrome and sum 0 <= w
        return True if 0 <= w else False

    # Check all elements are int or float
    if not all(isinstance(x, (int, float)) for x in elements):
        return False

    # Check palindrome
    if elements != elements[::-1]:
        return False

    # Check if sum is within weight limit
    if sum(elements) <= w:
        return True

    return False

