def mean_absolute_deviation(items):
    """Compute the mean absolute deviation (MAD) of a collection of numeric values.

    The MAD is the average absolute deviation from the arithmetic mean of the input.

    Args:
        items: An iterable of numeric values (supporting sum and division).

    Returns:
        A float representing the mean absolute deviation.

    Raises:
        ZeroDivisionError: If the input is empty.

    Examples:
        >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
        1.0
    """
    items = list(items)
    mean = sum(items) / len(items)  # May raise ZeroDivisionError if items is empty
    return sum(abs(x - mean) for x in items) / len(items)

