def parse_nested_parens(text):
    """
    The input is a string containing multiple groups of parentheses separated by whitespace.
    For each group, compute the maximum nesting depth of parentheses.
    Ignore any unbalanced parentheses without raising errors.
    Return a list of integers representing the maximum nesting depth for each group in input order.

    Examples:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]

    >>> parse_nested_parens('(()()) ()) (((())')
    [2, 1, 4]
    """
    results = []
    groups = text.split()

    for group in groups:
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                if current_depth > 0:
                    current_depth -= 1
                # If current_depth == 0, ignore unmatched closing parenthesis
        results.append(max_depth)

    return results

