def parse_music(tune_text):
    """Parse the input string of musical tokens separated by whitespace.

    Map each recognized token to its respective beats:
        'o'  -> 4
        'o|' -> 2
        '.|' -> 1

    Ignore any unrecognized tokens.

    Return a list of integers representing the beats of recognized tokens in order.
    """
    beat_map = {
        'o': 4,
        'o|': 2,
        '.|': 1,
    }

    tokens = tune_text.split()
    result = []
    for token in tokens:
        if token in beat_map:
            result.append(beat_map[token])
    return result

