def fizz_buzz(limit):
    """Return the total count of the digit '7' in decimal representations of all numbers less than limit
    that are divisible by 11 or 13.

    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
