def monotonic(seq):
    """Return True if the sequence is entirely monotonic,
    i.e., either non-decreasing throughout or non-increasing throughout.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 1, 1, 1])
    True
    """
    seq = list(seq)
    if len(seq) <= 1:
        return True
    non_decreasing = all(x <= y for x, y in zip(seq, seq[1:]))
    non_increasing = all(x >= y for x, y in zip(seq, seq[1:]))
    return non_decreasing or non_increasing

