def total_match(items1, items2):
    '''
    Takes two collections of strings and returns the collection whose total
    character count across all items is smaller. If tied, returns items1.

    The returned collection is the original input (not a copy), preserving order.

    Examples:
    total_match([], []) ➞ []
    total_match(['hi', 'admin'], ['hI', 'Hi']) ➞ ['hI', 'Hi']
    total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']) ➞ ['hi', 'admin']
    total_match(['hi', 'admin'], ['hI', 'hi', 'hi']) ➞ ['hI', 'hi', 'hi']
    total_match(['4'], ['1', '2', '3', '4', '5']) ➞ ['4']
    '''
    len1 = sum(len(item) for item in items1)
    len2 = sum(len(item) for item in items2)

    if len1 <= len2:
        return items1
    else:
        return items2

