def prime_length(item):
    """Return True if the length of `item` is a prime number, False otherwise.

    A prime number is an integer greater than 1 that has no positive divisors other than 1 and itself.
    For example:
    prime_length('Hello') == True  # length 5 is prime
    prime_length('abcdcba') == True  # length 7 is prime
    prime_length('kittens') == True  # length 7 is prime
    prime_length('orange') == False  # length 6 is not prime
    prime_length('') == False  # length 0 is not prime
    """
    n = len(item)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # Check odd divisors up to sqrt(n)
    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True

