def anti_shuffle(text):
    """
    Splits the input text on literal spaces only.
    Each space-separated token is replaced by the token's characters sorted ascending by character code.
    Spaces are preserved exactly in their original positions.
    """
    tokens = text.split(' ')
    sorted_tokens = [''.join(sorted(token)) for token in tokens]
