def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)
    # Since elements are distinct, sorted means strictly increasing.
    # We want to check if some rightward rotation of seq is sorted.
    # A rightward rotation by k means:
    # rotated_seq = seq[-k:] + seq[:-k]
    # We need to check for some k in [0, n-1] if rotated_seq is strictly increasing.

    for k in range(n):
        rotated = seq[-k:] + seq[:-k]
        # Check if rotated is strictly increasing
        if all(rotated[i] < rotated[i+1] for i in range(n-1)):
            return True

    return False

