def maximum(seq, count):
    """
    Given a sequence seq of values and a count count, return a sorted list 
    of length count with the top count items from seq.

    The top count items are the count largest items in seq.
    These are found by sorting seq in descending order, taking the first count elements,
    then returning them sorted in ascending order.

    Args:
        seq (sequence of int): Input sequence of integers.
        count (int): Number of top items to pick (0 <= count <= len(seq)).

    Returns:
        list of int: Sorted list of the top count items from seq.

    Examples:
        maximum([-3, -4, 5], 3) -> [-4, -3, 5]
        maximum([4, -4, 4], 2) -> [4, 4]
        maximum([-3, 2, 1, 2, -1, -2, 1], 1) -> [2]
    """
    # Sort seq in descending order and take top count items
    top_items = sorted(seq, reverse=True)[:count]
    # Return these top items sorted in ascending order
    return sorted(top_items)

