def digits(val):
    """Given a positive number val, return an overall multiplicative result of the odd digits.
    Produce 0 if none of the digits are odd.
    For example:
    digits(1)   == 1
    digits(4)   == 0
    digits(235) == 15
    """
    product = 1
    found_odd = False
    for ch in str(val):
        d = int(ch)
        if d % 2 == 1:
            product *= d
            found_odd = True
    return product if found_odd else 0

