def order_by_points(items):
    """
    Orders the supplied collection of integers based on the cumulative value of their digits,
    with the rule that for negative numbers only the first digit contributes negatively to the
    digit sum score (the rest are added as positive digits). For positive numbers, all digit sums
    are positive.

    Items are sorted ascending by this digit sum score, preserving original order for ties.

    Examples:
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, -1, 11, -11, -12]
    True
    >>> order_by_points([]) == []
    True
    """
    def digit_sum_score(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            # Negative number: first digit contributes negatively, rest positively
            return -digits[0] + sum(digits[1:]) if len(digits) > 1 else -digits[0]

    return sorted(items, key=digit_sum_score)

