def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    If shift == number of digits, return original digits.
    Otherwise, perform a circular right shift by shift modulo the number of digits.

    >>> circular_shift(12, 1)
    '12'
    >>> circular_shift(12, 2)
    '12'
    >>> circular_shift(12, 3)
    '21'
    >>> circular_shift(-1234, 2)
    '3412'
    >>> circular_shift(-1234, 4)
    '1234'
    >>> circular_shift(-1234, 5)
    '4321'
    """
    digits = str(abs(x))
    n = len(digits)

    if shift > n:
        # reverse digits
        result = digits[::-1]
    elif shift == n:
        # return original digits
        result = digits
    else:
