def anti_shuffle(s):
    """
    Write a function that takes a string and returns an ordered version of it.
    Ordered version of string, is a string where all words (separated by space)
    are replaced by a new word where all the characters arranged in
    ascending order based on ascii value.
    Note: You should keep the order of words and blank spaces in the sentence.

    For example:
    anti_shuffle('Hi') returns 'iH'
    anti_shuffle('hello') returns 'ollhe'
    anti_shuffle('Hello World!!!') returns 'roldW!!! olleH'

    Clarification:
    The function should preserve the original order of words and all spaces exactly as in the input,
    including multiple or irregular spaces, and within each word (defined as any sequence of non-space characters),
    all characters should be sorted in ascending ASCII order.
    """
    result = []
    word = []

    for char in s:
        if char == ' ':
            # On space, finish the previous word if any
            if word:
                sorted_word = ''.join(sorted(word))
                result.append(sorted_word)
                word = []
            # Append the space itself
            result.append(char)
        else:
            word.append(char)

    # Append last word if any
    if word:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)

    return ''.join(result)

