def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr.

    If k == 0, return an empty list.
    If k > 0, return exactly k elements, including duplicates if present,
    sorted ascending.

    Examples:
    - maximum([-3, -4, 5], 3) -> [-4, -3, 5]
    - maximum([4, -4, 4], 2) -> [4, 4]
    - maximum([-3, 2, 1, 2, -1, -2, 1], 1) -> [2]
    """
    if k == 0:
        return []
    # Sort arr descending to get max k elements
    sorted_desc = sorted(arr, reverse=True)
    top_k = sorted_desc[:k]
    # Return sorted ascending
    return sorted(top_k)

