def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers which are divisible by 11 or 13,
    counting only integers less than n (from 1 up to n-1 inclusive).

    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
