def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing,
    allowing equality (non-decreasing or non-increasing).

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([3, 3, 3])
    True
    >>> monotonic([])
    True
    >>> monotonic([5])
    True
    """
    if len(l) <= 1:
        return True

    non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
    non_increasing = all(x >= y for x, y in zip(l, l[1:]))

    return non_decreasing or non_increasing

