def anti_shuffle(s):
    """
    Write a function that takes a string and returns an ordered version of it.
    Ordered version of string, is a string where all words (separated by space)
    are replaced by a new word.
    Note: You should keep the order of words and blank spaces in the sentence.

    According to the user's clarification:
    - Preserve all original whitespace sequences exactly.
    - For each "word" (a sequence of non-space characters):
      - Sort all characters (letters and punctuation) in the word by their ASCII values.
      - The sorted characters replace the original word.
    - Do not separate alphabetic and non-alphabetic characters within a word.
    - Spaces remain exactly as in the input.

    Examples:
    anti_shuffle('Hi') returns 'Hi'  # 'Hi' sorted is 'Hi'
    anti_shuffle('hello') returns 'ehllo'
    anti_shuffle('Hello World!!!') returns 'Hello !!!Wdlor'
    """

    import re

    # Split input into sequences of spaces and non-space words, preserving order
    tokens = re.findall(r'\s+|\S+', s)

    result_tokens = []
    for token in tokens:
        if token.isspace():
            # Preserve space sequences as is
            result_tokens.append(token)
        else:
            # Sort all characters in the word by their ASCII values
            sorted_word = ''.join(sorted(token))
            result_tokens.append(sorted_word)

    return ''.join(result_tokens)

