def move_one_ball(arr):
    """We have an array 'arr' of N integers arr[1], arr[2], ..., arr[N].The
    numbers in the array will be randomly ordered. Your task is to determine if
    it is possible to get an array sorted in non-decreasing order by performing 
    the following operation on the given array:
        You are allowed to perform right shift operation any number of times.

    One right shift operation means shifting all elements of the array by one
    position in the right direction. The last element of the array will be moved to
    the starting position in the array i.e. 0th index. 

    If it is possible to obtain the sorted array by performing the above operation
    then return True else return False.
    If the given array is empty then return True.

    For Example:

    move_one_ball([3, 4, 5, 1, 2])==>True
    Explanation: By performin 2 right shift operations, non-decreasing order can
                 be achieved for the given array.
    move_one_ball([3, 5, 4, 1, 2])==>False
    Explanation:It is not possible to get non-decreasing order for the given
                array by performing any number of right shift operations.
    """
    if not arr:
        return True

    n = len(arr)
    count_breaks = 0
    break_index = -1

    # Count the number of descending breaks (arr[i] > arr[i+1])
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count_breaks += 1
            break_index = i
            if count_breaks > 1:
                return False

    # Also check the wrap-around break from last element to first element
    # This is necessary because a rotation can connect end to start
    if arr[-1] > arr[0]:
        # If there are no breaks inside the array, this wrap-around is a break
        if count_breaks == 0:
            count_breaks = 1
            break_index = n - 1
        else:
            # If there's already a break, this makes second break
            # So not possible
            return False

    if count_breaks == 0:
        # Already sorted, no rotation needed
        return True

    # If we have exactly one break, check if rotating right by (n - break_index - 1) sorts the array
    # The rotation moves the element at break_index + 1 to front
    # Let's build the rotated array and check if sorted non-decreasingly
    rotate_start = (break_index + 1) % n
    rotated = arr[rotate_start:] + arr[:rotate_start]

    # Check if rotated is non-decreasing
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False

    return True

