def select_words(s, n):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    if not s:
        return []
    result = []
    for word in s.split():
        # Extract only alphabetic characters from the word
        letters = [ch for ch in word if ch.isalpha()]
        # Count consonants (alphabetic letters not in vowels)
        consonant_count = sum(1 for ch in letters if ch.lower() not in vowels)
        if consonant_count == n:
            result.append(word)
    return result

