def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a list 
    of length k with the maximum k numbers in arr, sorted in ascending order.

    If k is 0, return an empty list.

    Example 1:
        Input: arr = [-3, -4, 5], k = 3
        Output: [-4, -3, 5]

    Example 2:
        Input: arr = [4, -4, 4], k = 2
        Output: [4, 4]

    Example 3:
        Input: arr = [-3, 2, 1, 2, -1, -2, 1], k = 1
        Output: [2]
    """
    if k == 0:
        return []
    # Sort arr descending, take first k elements, then sort ascending
    top_k = sorted(arr, reverse=True)[:k]
    return sorted(top_k)

