from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each group, output an integer representing the maximum depth of properly balanced nested parentheses,
    or 0 if the group contains unbalanced parentheses or invalid characters.
    """
    results = []
    groups = paren_string.split()

    for group in groups:
        max_depth = 0
        current_depth = 0
        valid = True

        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    # More closing parens than opening
                    valid = False
                    break
            else:
                # Invalid character found
                valid = False
                break

        if not valid or current_depth != 0:
            results.append(0)
        else:
            results.append(max_depth)

    return results

