def fizz_buzz(n: int) -> int:
    """
    Return the number of times the digit '7' appears in integers less than n
    which are divisible by 11 or 13.
    """
    count = 0
    for num in range(11, n, 11):
        count += str(num).count('7')
    for num in range(13, n, 13):
        # To avoid double counting multiples of 11*13=143, only count if not divisible by 11
        if num % 11 != 0:
