def sort_even(l: list):
    """
    This function takes a list l and returns a list l' such that:
    - Values at even indices of l' are the sorted values of the even indices of l, in ascending order.
    - Values at odd indices of l' are the same as in l.

    Example:
    sort_even([4, 3, 2, 1, 0]) returns [0, 3, 2, 1, 4]
    """
    # Extract the elements at even indices
    even_values = [l[i] for i in range(0, len(l), 2)]
    # Sort the even indexed elements
    even_values.sort()

    # Create a copy of the original list to preserve odd indexed elements
    result = l[:]

    # Replace even indices with the sorted even values
    even_index = 0
    for i in range(0, len(l), 2):
        result[i] = even_values[even_index]
        even_index += 1

    return result

