def monotonic(l: list) -> bool:
    """
    Returns True if the list l is monotonic (entirely non-decreasing or entirely non-increasing), False otherwise.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([2, 2, 2, 2])
    True
    """
    if not l:
        return True  # empty list can be considered monotonic

    non_decreasing = all(l[i] <= l[i+1] for i in range(len(l) - 1))
    non_increasing = all(l[i] >= l[i+1] for i in range(len(l) - 1))

    return non_decreasing or non_increasing

