def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits
    and return the result as a string.

    Positive shift values rotate the digits to the right,
    and negative shift values rotate the digits to the left by the corresponding
    amount modulo the number of digits.

    The sign of x is preserved.
    """
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return '-' if x < 0 else ''
    # Normalize shift to be within the length of s
    shift = shift % n
    # For negative shifts, rotate to the left
    # Equivalent to rotating right by (n - abs(shift)) mod n
    # But since we used modulo, positive shift is right rotation.
    # If original shift was negative, shift is adjusted as follows:
    # Because shift = shift % n, negative shift % n is equivalent to n - abs(shift) % n
    # So we can just use the normalized shift as is to slice right rotation.
    # So this is correct.

    rotated = s[-shift:] + s[:-shift] if shift != 0 else s
    return '-' + rotated if x < 0 else rotated

