def prime_length(s):
    """
    Returns True if the length of the input string s is a prime number,
    otherwise returns False.

    Examples:
    prime_length('ab') == True   # length 2 is prime
    prime_length('Hello') == True  # length 5 is prime
    prime_length('orange') == False  # length 6 is not prime
    prime_length('abcdcba') == True  # length 7 is prime
    prime_length('kittens') == True  # length 7 is prime
    """
    n = len(s)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # check odd factors up to sqrt(n)
    limit = int(n ** 0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True

