def anti_shuffle(s):
    """
    Takes a string s, treats spaces as separators between words,
    sorts the characters within each word in ascending order,
    and returns a new string with spaces preserved in their original positions.
    """
    result_chars = list(s)  # convert to list for mutable assignment
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            i += 1
            continue
        # find word boundaries
        start = i
        while i < n and s[i] != ' ':
            i += 1
        end = i
        # sort the characters in the word
        sorted_word = sorted(s[start:end])
        # replace in result_chars
        result_chars[start:end] = sorted_word
    return ''.join(result_chars)

