def select_words(s, n):
    """Given a string s and a natural number n, return a list of all words from s
    that contain exactly n consonants. Words are separated by whitespace, and
    punctuation and other characters are included as part of the words.

    Consonants are letters that are alphabetic and not vowels (a, e, i, o, u),
    case-insensitive.
    """
    vowels = set('aeiouAEIOU')
    result = []
    words = s.split()
    for word in words:
        consonant_count = sum(1 for c in word if c.isalpha() and c not in vowels)
        if consonant_count == n:
            result.append(word)
    return result

