def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k containing the k largest elements from arr, including duplicates.
    If arr has fewer than k elements, return all elements sorted ascending.

    Parameters:
    - arr: List[int] -- list of integers
    - k: int -- positive integer specifying how many largest elements to return

    Returns:
    - List[int] -- sorted list (ascending) of length min(k, len(arr)) containing the k largest elements
    """
    # Sort the array in descending order to get largest elements first
    sorted_desc = sorted(arr, reverse=True)
    # Take the first k elements (or all if fewer)
    top_k = sorted_desc[:k]
    # Return sorted ascending
    return sorted(top_k)

