def sum_squares(lst):
    """
    This function will take a list of integers. The function will not 
    change the entries in the list whose indexes are not a multiple of 3 or 4. 
    The function shall then return the sum of all entries. 

    Clarified behavior:
    - If an index is a multiple of 3, square the element at that index.
    - Otherwise, if the index is a multiple of 4 (but not 3), cube the element at that index.
    - Otherwise, leave the element unchanged.

    Examples:
    For lst = [1,2,3] the output should be 6
    For lst = [] the output should be 0
    For lst = [-1,-5,2,-1,-5] the output should be -126
    For lst = [2,3,4,5,6] the output should be 72
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
