def order_by_points(nums):
    """
    Sorts the input list of integers based on the sum of their digits with the following rules:

    - If the number is negative, its first digit is treated as negative in the digit sum.
      For example, for -12, digit sum = -1 + 2 = 1.
    - If the number is non-negative, all digits are summed normally.
    - Ties in digit sum are broken by the original index (stable sort by index).

    Examples:
    >>> order_by_points([1, 11, -1, -11, -12])
    [-1, -11, 1, -12, 11]
    >>> order_by_points([])
    []
    >>> order_by_points([10, -2, 21, -11])
    [10, -2, -11, 21]
    """
    def digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)

    # Pair each number with its digit sum and original index
    decorated = [(digit_sum(num), idx, num) for idx, num in enumerate(nums)]
    # Sort by digit sum, then by original index
    decorated.sort(key=lambda x: (x[0], x[1]))
    # Extract the sorted numbers
    return [num for _, _, num in decorated]

