def parse_nested_parens(paren_string):
    """
    Input: a string containing multiple groups of parentheses separated by spaces.
    Output: a list of integers, each integer representing the deepest level of nesting
    of balanced parentheses in the corresponding group.

    Rules:
    - For each group (substring separated by spaces), compute the maximum nesting depth.
    - Ignore unmatched closing parentheses (do not decrease depth below zero).
    - Do not penalize unmatched opening parentheses (i.e., do not reduce max depth because 
      of them).
    - Return 0 for groups with no valid nested parentheses.

    Example:
    parse_nested_parens('(()) ((())) () ()())') -> [2, 3, 1, 1]
    """
    results = []
    groups = paren_string.split()

    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                if current_depth > 0:
                    current_depth -= 1
                # else ignore unmatched closing parenthesis
        results.append(max_depth)

    return results

