def parse_music(s: str) -> list[int]:
    """
    Parse a string of space-separated musical note tokens into a list of beats.

    Legend:
    'o'  - whole note, 4 beats
    'o|' - half note, 2 beats
    '.|' - quarter note, 1 beat

