def sort_even(l):
    """This function takes a list l and returns a new list where the elements at even indices are sorted in ascending order,
    and elements at odd indices remain unchanged."""
    # Extract elements at even indices
    even_elements = [l[i] for i in range(0, len(l), 2)]
    # Sort the even elements
    even_elements.sort()

    # Create a copy of the original list to preserve odd elements
    result = l[:]

    # Replace elements at even indices with sorted even elements
    for idx, val in zip(range(0, len(l), 2), even_elements):
        result[idx] = val

    return result

