def monotonic(lst):
    """Return True if list elements are monotonically non-decreasing or non-increasing.

    An empty list is considered monotonic.
    Adjacent equal elements are allowed.

    Args:
        lst: A list or list-like ordered sequence of comparable elements.

    Returns:
        bool: True if lst is monotonic, False otherwise.
    """
    if not lst:
        return True

    non_decreasing = all(x <= y for x, y in zip(lst, lst[1:]))
    non_increasing = all(x >= y for x, y in zip(lst, lst[1:]))

    return non_decreasing or non_increasing

