def circular_shift(x, shift):
    """Circular shift the digits of x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed as a string,
    preserving any leading zeros in the output.
    """
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    if shift == 0:
        return s
    shift %= n
    return s[-shift:] + s[:-shift]

