def smallest_change(arr):
    """
    Find the minimum number of elements that need to be changed to make the array palindromic.

    This is done by counting the number of symmetric element pairs that differ.

    Args:
        arr: A list-like sequence supporting length and indexing,
             containing elements comparable by equality.

    Returns:
        int: The minimum number of changes needed to make the array palindromic.
    """
    count = 0
    n = len(arr)
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count

