import re

def select_words(s, n):
    """
    Returns a list of all words from string s that contain exactly n consonants,
    in the order these words appear in s.

    Words are contiguous alphabetic sequences separated by non-alphabetic characters.
    Consonants are English letters other than a, e, i, o, u counted case-insensitively.
    """
    vowels = set('aeiouAEIOU')
    words = re.findall(r'[A-Za-z]+', s)
    result = []
    for word in words:
        consonant_count = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result

