from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input string contains multiple groups separated by literal space characters.
    Each non-empty space-separated chunk is treated as one group.
    For each group, compute the maximum nesting depth of parentheses,
    ignoring any non-parenthesis characters inside the group.

    Example:
    parse_nested_parens('(()()) ((())) () ((())()())') returns [2, 3, 1, 3]
    """
    def max_depth(group: str) -> int:
        depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
        return max_depth

    groups = [g for g in paren_string.split(' ') if g]
    return [max_depth(group) for group in groups]

