def fizz_buzz(n: int) -> int:
    """
    Count the number of times the digit '7' appears in integers i with 0 <= i < n
    where i is divisible by 11 or 13.

    >>> fizz_buzz(50)
    2
    >>> fizz_buzz(78)
    4
    >>> fizz_buzz(79)
    4
    """
