def sort_even(l: list):
    """
    This function takes a list l and returns a new list l' such that:
    - The values at odd indices remain the same as in l.
    - The values at even indices are replaced by the values of the even indices of l, sorted ascendingly.

    Examples:
    >>> sort_even([1, 2, 3])
    [1, 2, 3]
    >>> sort_even([5, 6, 3, 4])
    [3, 6, 5, 4]
    """

    # Extract values at even indices and sort ascendingly
    even_values = sorted(l[0::2])
    result = l[:]  # copy original list to preserve odd indices

    # Replace even indices with sorted even values
    even_idx = 0
    for i in range(0, len(l), 2):
        result[i] = even_values[even_idx]
        even_idx += 1

    return result

