def triples_sum_to_zero(l: list) -> bool:
    """
    Returns True if there exist three distinct elements in the list whose sum is zero.
    Returns False if the list has fewer than three elements or no such triple exists.

    >>> triples_sum_to_zero([1, 3, 5, 0])
    True
    >>> triples_sum_to_zero([1, 3, -2, 1])
    False
    >>> triples_sum_to_zero([1, 2, 3, 7])
    True
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    False
    >>> triples_sum_to_zero([1])
    False
    """
    n = len(l)
    if n < 3:
        return False

    # Use a classic 3-sum approach: sort and use two pointers
    l_sorted = sorted(l)
    for i in range(n - 2):
        # Avoid duplicates for i not strictly required, but harmless
        if i > 0 and l_sorted[i] == l_sorted[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            s = l_sorted[i] + l_sorted[left] + l_sorted[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False

