def monotonic(l: list) -> bool:
    """
    Return True if the list elements are monotonic (either nondecreasing or nonincreasing), False otherwise.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 1])
    False
    >>> monotonic([5])
    True
    >>> monotonic([])
    True
    """
    if len(l) <= 1:
        return True

    nondecreasing = all(x <= y for x, y in zip(l, l[1:]))
    nonincreasing = all(x >= y for x, y in zip(l, l[1:]))

    return nondecreasing or nonincreasing

