def circular_shift(x, shift):
    """
    Circular shift the digits of the integer x to the right by shift positions,
    and return the result as a string.
    If shift is equal to or greater than the number of digits, return the digits reversed.

    >>> circular_shift(12, 1)
    '12'
    >>> circular_shift(12, 2)
    '21'
    """
    digits = str(abs(x))
    n = len(digits)
    if shift >= n:
        return digits[::-1]
    # Circular shift right by shift positions
    shift = shift % n
    return digits[-shift:] + digits[:-shift]

