def smallest_change(arr):
    """
    Given an array arr of integers, returns the minimum number of changes required to make the array palindromic.
    Each change can modify one element to any other element.
    The minimum number of changes equals the count of mismatched mirrored pairs.
    """
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

