def maximum(arr, k):
    """
    Given an array arr of integers and a non-negative integer k, return a sorted list 
    of length k with the maximum k numbers in arr (including duplicates).
    If k is 0, return an empty list.
    If k is greater than the length of arr, return all elements sorted.

    Examples:
    maximum([-3, -4, 5], 3) -> [-4, -3, 5]
    maximum([4, -4, 4], 2) -> [4, 4]
    maximum([-3, 2, 1, 2, -1, -2, 1], 1) -> [2]
    maximum([-3, 2, 1, 2, -1, -2, 1], 0) -> []
    """
    if k == 0:
        return []
    # Sort arr in descending order and take top k elements
    top_k = sorted(arr, reverse=True)[:k]
    # Return ascending sorted list of these elements
    return sorted(top_k)

