def sum_squares(lst):
    """
    This function takes a list of integers. For all entries in the list:
    - If the index is a multiple of 3, the integer is squared.
    - If the index is a multiple of 4 but not a multiple of 3, the integer is cubed.
    - Otherwise, the integer remains unchanged.
    The function returns the sum of all resulting values.
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

