def get_gcd(numbers):
    from math import gcd
    if not numbers:
        return 0
    # Filter out zeros since gcd(0, x) = x, but if all zero, result should be 0
    filtered = [abs(num) for num in numbers]
    if all(num == 0 for num in filtered):
        return 0
    current_gcd = filtered[0]
    for num in filtered[1:]:
        current_gcd = gcd(current_gcd, num)
    return current_gcd

