def zip_tuples(*tuples):
    if not tuples:
        return []
    first, *rest = tuples
    n = len(first)
    # If there is only one tuple, just return its elements as single-element tuples
    if not rest:
        return [(x,) for x in first]
    # For each position in the first tuple, create a tuple with first[i] and the corresponding elements from the other tuples,
    # cycling through them as needed.
    result = []
    for i in range(n):
        zipped = [first[i]]
        for t in rest:
            zipped.append(t[i % len(t)])
        result.append(tuple(zipped))
    return result

