def next_smallest_palindrome(num: int) -> int:
    """
    Returns the smallest palindrome integer strictly greater than the input number.

    Args:
        num (int): A non-negative integer input.

    Returns:
        int: The next smallest palindrome greater than num.
    """
    s = str(num)

    # If all digits are '9', the next palindrome is '1' + '0'*(len(s)-1) + '1'
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (len(s) - 1)) + '1')

    length = len(s)
    half = length // 2
    odd_len = (length % 2 != 0)

    # Split the original number into left, middle (if odd), and right parts
    if odd_len:
        left = s[:half]
        middle = s[half]
        right = s[half + 1:]
    else:
        left = s[:half]
        middle = ''
        right = s[half:]

    # Create a palindrome by mirroring left + middle
    if odd_len:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > num:
        return int(palindrome)

    # Increment the middle part and handle carry
    if odd_len:
        # Increment the middle digit
        middle_int = int(middle) + 1
