def find_solution(a: int, b: int, n: int):
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    Search x from 0 upwards and return the first valid (x, y) pair.
    If no such solution exists, return "No solution".
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"

    # If a == 0, then b*y = n => y = n/b if divisible and non-negative
    if a == 0:
        if b != 0 and n % b == 0 and (n // b) >= 0:
            return (0, n // b)
        else:
            return "No solution"

    # If b == 0, then a*x = n => x = n/a if divisible and non-negative
    if b == 0:
        if a != 0 and n % a == 0 and (n // a) >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    # For x >= 0, check if y = (n - a*x)/b is integer and non-negative
    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1

    return "No solution"

