def find_exponentio(bases, exponents):
    """
    Perform element-wise exponentiation on two tuples of numeric elements.

    Args:
        bases (tuple): Tuple of numeric bases.
        exponents (tuple): Tuple of numeric exponents.

    Returns:
        tuple: Tuple of results from element-wise base ** exponent,
               truncated to the length of the shorter input tuple.
    """
    length = min(len(bases), len(exponents))
    return tuple(bases[i] ** exponents[i] for i in range(length))

