def decode_list(encoded):
    """
    Decode a run-length encoded list.

    The input is a flat list where elements can be either:
    - a list [count, value], where count is a non-negative integer,
      indicating the value should be repeated count times, or
    - a standalone value, which should be included once.

    Returns a flat list with values repeated according to the counts,
    preserving the input order.

    Examples:
    >>> decode_list([[2, 'x'], 'y', [3, 'z']])
    ['x', 'x', 'y', 'z', 'z', 'z']

    >>> decode_list(['a', [0, 'b'], [1, 'c']])
    ['a', 'c']
    """
    result = []
    for item in encoded:
        if isinstance(item, list) and len(item) == 2:
            count, value = item
            if count > 0:
                result.extend([value] * count)
            # if count == 0, skip
        else:
            # standalone value, include once
            result.append(item)
    return result

