def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Counts the number of sequences of length n where each element is an integer between 1 and m,
    and each next element is at least twice the previous element.

    Parameters:
    - m (int): maximum allowed element value
    - n (int): length of the sequences

    Returns:
    - int: number of valid sequences
    """
    if n == 1:
        # Any element from 1 to m is a valid sequence of length 1
        return m

    # dp[i][x] = number of sequences of length i ending with element x
    # To optimize memory, we keep only the previous row
    dp_prev = [1] * (m + 1)  # for sequences of length 1, every element counts as 1
    dp_prev[0] = 0  # 0 is not a valid element

    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)

        # For each possible current element x, the previous element y must satisfy y <= x // 2
        # So sum dp_prev[y] for y in [1, x//2]

        # To speed up sum queries, build prefix sums of dp_prev
        prefix_sum = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix_sum[max_prev]
            else:
                dp_curr[x] = 0

        dp_prev = dp_curr

    return sum(dp_prev[1:])  # sum over sequences of length n ending with any element


