def min_flip_to_make_string_alternate(s: str) -> int:
    """
    Given a binary string s containing only '0' and '1',
    return the minimum number of flips required to make
    the string alternate between '0' and '1'.

    The two possible alternating patterns are:
    - starting with '0': "010101..."
    - starting with '1': "101010..."

    The function returns the minimal flips needed to convert
    s into either of these patterns.
    """
    # Pattern 1: start with '0'
    flips_start_0 = 0
    # Pattern 2: start with '1'
    flips_start_1 = 0

    for i, ch in enumerate(s):
        expected_char_0 = '0' if i % 2 == 0 else '1'
        expected_char_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_char_0:
            flips_start_0 += 1
        if ch != expected_char_1:
            flips_start_1 += 1

    return min(flips_start_0, flips_start_1)

