def find_remainder(nums, b, n):
    """
    Compute the remainder of (product of all integers in nums multiplied by b) divided by n.

    Args:
        nums (list of int): list of integers to multiply
        b (int): an integer factor
        n (int): the divisor

    Returns:
        int: remainder of (product_of_nums * b) % n

    Raises:
        ValueError: if n == 0
    """
    if n == 0:
        raise ValueError("Divisor n cannot be zero")

    product = 1
    for num in nums:
        product = (product * num) % n

    product = (product * b) % n
    return product

