from typing import List, Optional

def find_Max(nums: List[int]) -> Optional[int]:
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    # If the array is not rotated (the smallest element is at index 0),
    # the maximum is the last element.
    if nums[left] < nums[right]:
        return nums[right]

    # Binary search to find the index of the smallest element (pivot)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # left is now the index of the smallest element (pivot)
    # The maximum element is the one immediately before the pivot,
    # taking care to wrap around if pivot is at index 0.
    max_index = (left - 1) % len(nums)
    return nums[max_index]
find_max = find_Max

