from math import comb

def sum_Of_product(n: int) -> int:
    """
    Compute the sum of products of adjacent binomial coefficients for a given n:
    sum_{k=0}^{n-1} C(n, k) * C(n, k+1) = C(2n, n-1)

    Parameters:
    n (int): A non-negative integer, n >= 1

    Returns:
    int: The sum of the products of adjacent binomial coefficients.

    Raises:
    ValueError: If n < 1
    """
