def recur_gcd(a: int, b: int) -> int:
    # If both inputs are zero, return 0 as specified
    if a == 0 and b == 0:
        return 0

    # Use absolute values for gcd computation
    a, b = abs(a), abs(b)

    # Recursive Euclidean algorithm
    if b == 0:
        return a
    else:
        return recur_gcd(b, a % b)

