def capital_words_spaces(s: str) -> str:
    """
    Insert spaces before uppercase letters that start a new word,
    where a new word is defined as an uppercase letter immediately
    preceded by a lowercase letter.

    Consecutive uppercase letters are grouped together as a single word block.

    Examples:
    - "XMLHTTPParser" -> "XMLHTTP Parser"
    - "ThisIsATest" -> "This Is A Test"
    - "simpleTest" -> "simple Test"
    - "Already Spaced" -> "Already Spaced"
    """
    result = []
    for i, c in enumerate(s):
        if i > 0 and c.isupper() and s[i-1].islower():
            result.append(' ')
        result.append(c)
    return ''.join(result)

