def substract_elements(t1, t2):
    """
    Subtract elements of two nested tuples element-wise.

    Args:
        t1: A nested tuple of numbers (int or float).
        t2: A nested tuple of numbers (int or float).

    Returns:
        A nested tuple or number representing t1 - t2 element-wise.

    Raises:
        ValueError: If the structures of t1 and t2 do not match.
    """
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        if len(t1) != len(t2):
            raise ValueError("Tuples have different lengths")
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))
    elif isinstance(t1, (int, float)) and isinstance(t2, (int, float)):
        return t1 - t2
    else:
        raise ValueError("Tuple structures do not match")

