def dif_Square(value: int) -> bool:
    # difference of squares: value = a^2 - b^2 = (a-b)(a+b)
    # let x = a-b, y = a+b
    # then value = x * y, and (x + y) must be even (since x+y = 2a)
    # So, for some integer factors x,y of value, (x+y) is even

    # Special case: 0 = 0^2 - 0^2
    if value == 0:
        return True

    # To find integer factors x,y such that x*y = value and (x+y) even
    # We can iterate over all integer divisors of value.
    # For negative values, factors can be negative as well.
    # So we consider all divisors d where d divides value.
    # For each divisor d, corresponding factor is value // d.

    # To cover negative factors, we consider all d in range from -abs(value) to abs(value)
    # excluding zero.

    abs_val = abs(value)
    # If value != 0, range of possible factors is from -abs_val to abs_val excluding 0
    # We'll check all divisors d of value in that range.

    # But to be more efficient, we only need to check divisors from 1 to abs_val
    # and consider both positive and negative pairs:
    # (d, value//d) and (-d, -value//d)

    for d in range(1, abs_val + 1):
        if value % d == 0:
            x, y = d, value // d
            # check (x + y) even:
            if (x + y) % 2 == 0:
                return True
            # check negative pair:
            x_neg, y_neg = -d, -value // d
            if (x_neg + y_neg) % 2 == 0:
                return True

    return False
