def Find_Min_Length(groups):
    """
    Given a list of groups (each group is a list of numeric part sizes),
    return the single smallest numeric part size among all groups combined.
    If there is only one group, return that group's smallest part size as a single integer.
    If all groups are empty or input is empty, return None.
