def next_smallest_palindrome(n: int) -> int:
    """
    Returns the smallest palindrome integer strictly greater than n.
    If no such palindrome exists (practically impossible for integers), returns -1.
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    candidate = n + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1
        # To prevent infinite loop theoretically, but practically unnecessary
        # since palindrome numbers are infinite.
        if candidate > 10**18:  
            return -1

