def sort_sublists(collection):
    """
    Given a sequence of subsequences (e.g., list of lists or tuples),
    return a new list where each subsequence is sorted in ascending order
    based on the first element of each item within that subsequence.

    Each sorted subsequence is returned as a list.

    Example:
    sort_sublists([[ (3, 'a'), (1, 'b'), (2, 'c') ], [ (5, 'x'), (4, 'y') ]])
    returns:
    [[(1, 'b'), (2, 'c'), (3, 'a')], [(4, 'y'), (5, 'x')]]
    """
    result = []
    for subseq in collection:
        # Sort the subsequence by the first element of each item
        sorted_subseq = sorted(subseq, key=lambda x: x[0])
        # Convert to list and append to result
        result.append(list(sorted_subseq))
    return result

