def find_solution(a: int, b: int, n: int):
    """
    Find the first valid non-negative integer solution (x, y) to the equation:
        a*x + b*y = n
    If such a solution exists, return (x, y) with x >= 0, y integer (any integer),
    choosing the first x >= 0 (starting from 0 upwards) for which y is integer.
    If no such solution exists, return 'No solution'.

    Special cases:
    - If a == 0 and b == 0:
        - If n == 0, return (0, 0)
        - else return 'No solution'
    - If a == 0:
        - Then equation is b*y = n
        - y = n/b if b divides n exactly, x can be 0 (non-negative)
    - If b == 0:
        - Then a*x = n
        - x = n/a if a divides n exactly and x >= 0, y can be 0

    Otherwise:
    - For x in 0..(some reasonable upper bound or until solution found):
        - Check if y = (n - a*x)/b is integer
        - If integer, return (x, y)
    - If no solution found, return 'No solution'

    We must be careful to avoid infinite loops if b == 0 or a == 0.

    Since no explicit upper bound was given, we will scan x from 0 up to a certain large limit (e.g., 10^6)
    to find the first non-negative integer x that yields integer y.

    If no solution found in that range, return 'No solution'.
    """
    # Handle the case a == 0 and b == 0
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return 'No solution'

    # Handle the case a == 0
    if a == 0:
        if b == 0:
            # Already handled above
            return 'No solution'
        # Equation: b*y = n
        if b != 0 and n % b == 0:
            y = n // b
            x = 0  # x can be zero
            return (x, y)
        else:
            return 'No solution'

    # Handle the case b == 0
    if b == 0:
        # Equation: a*x = n
        if n % a == 0:
