def get_total_number_of_sequences(N: int, K: int) -> int:
    """
    Counts the number of ordered sequences of length K where:
    - Each element is between 1 and N inclusive.
    - For each consecutive pair (a_i, a_{i+1}), a_{i+1} >= 2 * a_i.

    Args:
        N (int): Maximum value allowed in the sequence.
        K (int): Length of the sequence.

    Returns:
        int: Total count of valid sequences.
    """
    # dp[i][x] = number of sequences of length i ending with element x
    dp = [ [0] * (N + 1) for _ in range(K + 1) ]

    # Base case: sequences of length 1, any element from 1 to N
    for x in range(1, N + 1):
        dp[1][x] = 1

    # Fill dp for sequences of length 2 to K
    for length in range(2, K + 1):
        for curr in range(1, N + 1):
            # Find all previous elements prev where curr >= 2 * prev
            # i.e. prev <= curr // 2
            max_prev = curr // 2
            if max_prev >= 1:
                dp[length][curr] = sum(dp[length - 1][1:max_prev + 1])

    # Total sequences of length K
    return sum(dp[K][1:N + 1])

