def even_binomial_Coeff_Sum(n: int) -> int:
    """
    Calculate the sum of binomial coefficients C(n, k) for all even k between 0 and n inclusive.

    Based on the identity:
    sum_{k even} C(n, k) = 2^(n-1) for n > 0
    and equals 1 for n = 0.

    Parameters:
    n (int): Non-negative integer representing the upper index of binomial coefficients.

    Returns:
    int: Sum of binomial coefficients at even indices.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 1
    return 2 ** (n - 1)
