def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    if not d:
        # Empty dict counts as depth 1 if nested, but here it's top-level empty dict => 0
        return 0
    max_child_depth = 0
    for v in d.values():
        child_depth = dict_depth(v)
        if child_depth > max_child_depth:
            max_child_depth = child_depth
    return 1 + max_child_depth

