def diff_consecutivenums(nums):
    """
    Calculate the differences between adjacent entries in the input sequence.

    Args:
        nums: A sequence of numbers supporting len() and indexing.

    Returns:
        A list of numeric differences where each element is the subtraction of 
        the current number from the next number in input order.
        Returns an empty list if the input has fewer than two elements.
    """
    if len(nums) < 2:
        return []
    return [nums[i+1] - nums[i] for i in range(len(nums) - 1)]

