def remove_column(data, index):
    """
    Remove the element at position `index` from each inner grouping in `data` if possible.
    For each inner grouping in `data`:
      - If it is indexable (supports __getitem__) and has length > index,
        remove the element at `index`.
      - Preserve the type of the inner grouping (list, tuple, string, etc.).
      - If not indexable or too short, leave unchanged.
    Return a list of the processed inner groupings.

    Examples:
    >>> remove_column([[1, 2, 3], (4, 5, 6), 'abc', [7], 42], 1)
    [[1, 3], (4, 6), 'ac', [7], 42]
    """
    result = []
    for inner in data:
        # Check if inner is indexable and has length > index
        try:
            length = len(inner)
            if length > index:
                # Remove element at index, preserve type
                if isinstance(inner, str):
                    # Strings are immutable, create new string without char at index
                    new_inner = inner[:index] + inner[index+1:]
                elif isinstance(inner, tuple):
                    # Create new tuple without element at index
                    new_inner = inner[:index] + inner[index+1:]
                elif isinstance(inner, list):
                    # Create new list without element at index
                    new_inner = inner[:index] + inner[index+1:]
                else:
                    # For other sequence types that support slicing and concatenation,
                    # attempt to reconstruct by type if possible
                    # Otherwise, fallback to list and try to cast back
                    try:
                        # Try slicing and concatenation
                        new_inner = inner[:index] + inner[index+1:]
                    except Exception:
                        # Fallback: convert to list, remove element, try to cast back
                        temp_list = list(inner)
                        del temp_list[index]
                        try:
                            new_inner = type(inner)(temp_list)
                        except Exception:
                            # If casting back fails, return as list
                            new_inner = temp_list
                result.append(new_inner)
            else:
                # too short, leave unchanged
                result.append(inner)
        except TypeError:
            # not indexable, leave unchanged
            result.append(inner)
    return result

