def repeat_tuples(groups, times):
    if times <= 0:
        return [] if isinstance(groups, (list, tuple)) and (not isinstance(groups[0], tuple) or isinstance(groups, list)) else ()

    # If input is a single tuple (not a list of tuples)
    if isinstance(groups, tuple) and (not groups or not isinstance(groups[0], tuple)):
        # Return a tuple containing the single tuple repeated times times
        return tuple([groups] * times)

    # Otherwise, input is list of tuples (or tuple of tuples)
    # produce a flat list where each tuple is repeated times times consecutively
    result = []
    for group in groups:
        result.extend([group] * times)
    return result

