def smallest_missing(nums):
    """
    Returns the smallest non-negative integer missing from the sorted input list nums.

    Args:
        nums (List[int]): A sorted list of integers in ascending order.

    Returns:
        int: The smallest non-negative integer not present in nums.
    """
    expected = 0
    for num in nums:
        if num < expected:
            # num is less than expected, ignore since we only look for the smallest missing non-negative int
            continue
        elif num == expected:
            expected += 1
        elif num > expected:
            # Found a gap: expected is missing
            return expected
    return expected

