def multi_list(rows=3, cols=3, fill=None):
    """
    Create a list of lists with the given number of rows and columns.
    Each element is unique and not the same fixed value.

    Since the user clarified that elements should not all be the same fixed value,
    we will fill the matrix with unique values. A simple way is to fill with 
    increasing integers starting at 0, row-wise.

    Example:
    multi_list(2, 4, 0) -> [[0, 1, 2, 3], [4, 5, 6, 7]]
    """
    result = []
    count = 0
    for _ in range(rows):
        row = []
        for _ in range(cols):
            row.append(count)
            count += 1
        result.append(row)
    return result

