def check_greater(lst, num):
    """
    Takes a list and a single number, sorts the list, and returns True if the given number
    is strictly greater than the largest element in the list, otherwise False.

    Args:
        lst (list): A list of comparable items.
        num: A single comparable item.

    Returns:
        bool: True if num > largest element in lst, False otherwise.
    """
    if not lst:
        # If the list is empty, num is greater than "largest" element by default
        # since there is no largest element.
        return True
    sorted_lst = sorted(lst)
    largest = sorted_lst[-1]
    return num > largest

