from typing import List, Optional, Any

def find_Max(arr: List[Any], left: int = 0, right: Optional[int] = None) -> Optional[Any]:
    """
    Find the greatest element in a shifted (rotated) sorted sequence.

    Parameters:
    - arr: List[Any] -- list of comparable elements originally sorted ascending, then rotated.
    - left: int -- left index for binary search (default 0).
    - right: Optional[int] -- right index for binary search (default None means len(arr)-1).

    Returns:
    - The greatest element in the sequence, or None if the list is empty.

    Explanation:
    The greatest element is the element immediately before the minimum element.
    The minimum element is found via binary search.
    If the list is not rotated (fully sorted ascending), the greatest element is the last element.
    """
    if not arr:
        return None

    if right is None:
        right = len(arr) - 1

    # If the list is not rotated (last element >= first element), return last element
    if arr[right] >= arr[left]:
        return arr[right]

    while left <= right:
        mid = (left + right) // 2
        # Check if mid is the minimum element
        # mid > 0 to avoid index error
        if mid > 0 and arr[mid] < arr[mid - 1]:
            # The element before min is the max
            return arr[mid - 1]
        # Check if mid+1 is minimum element
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]

        # Decide which side to search next
        if arr[mid] >= arr[left]:
            # Left part is sorted, so min must be in right part
            left = mid + 1
        else:
            # Right part is sorted, min in left part
            right = mid - 1

    # Fallback, should not reach here if input is a rotated sorted list
    return None
