def sum_Of_product(n: int) -> int:
    """
    Returns the sum of the products of all k-element combinations chosen from the integers 1 through n,
    for k = 0 to n.

    In other words, this is the sum of elementary symmetric polynomials of the set {1, 2, ..., n} over all degrees.

    Since the sum over all subsets' products (including the empty subset) is:
        (1 + 1) * (1 + 2) * (1 + 3) * ... * (1 + n) = (n+1)!

    and the empty subset product is 1 (for k=0),

    the sum_Of_product(n) = (n+1)!.

    Args:
        n (int): The size of the set {1..n}.

    Returns:
        int: The sum of the products of all subsets of {1..n}, including the empty subset.
    """
    from math import factorial
    return factorial(n + 1)
