import re

def move_num(s: str) -> str:
    # Extract all numeric substrings
    nums = re.findall(r'\d+', s)
    # Remove all digits from the string
    text_no_digits = re.sub(r'\d', '', s)
    # Normalize spaces: split and join to remove extra spaces
    text_parts = text_no_digits.split()
    text = ' '.join(text_parts)
    # Concatenate numbers directly at the end without spaces
    return text + ''.join(nums)

