def str_to_tuple(s: str) -> tuple[int, ...]:
    s = s.strip()
    if not s:
        return ()
    parts = s.split(',')
    result = []
    for part in parts:
        part = part.strip()
        if not part:
            # This means there was something like "1,,2" or trailing comma like "1,2,"
            # which will cause empty string segments.
            raise ValueError("Empty segment found when parsing integers")
        try:
            num = int(part)
        except ValueError as e:
            raise ValueError(f"Invalid integer value: {part}") from e
        result.append(num)
    return tuple(result)

