def text_match(text: str) -> list[str]:
    """
    Find all minimal-length substrings of 'text' that contain the internally predefined pattern
    as a subsequence in order (allowing other characters in between).
    Return a list of unique matched substrings sorted by length ascending then lexicographically.
    Return [] if the pattern is empty or no matches.

    The pattern is predefined internally.

    Based on the original example and clarification, the pattern is 'abc'.
    """
    pattern = 'abc'
    if not pattern or not text:
        return []

    n = len(text)
    m = len(pattern)

    results = set()
    min_len = None

    # For each occurrence of the first pattern character, try to find minimal substring
    # containing the whole pattern as subsequence starting from that position.
    for start in range(n):
        if text[start] != pattern[0]:
            continue

        # We will try to find the minimal substring starting at start that contains pattern as subsequence.
        # Use a pointer p to pattern and i to text
        p = 1  # we matched pattern[0] at start
        i = start + 1
