import re

def capital_words_spaces(text: str) -> str:
    """
    Adjust spacing in the text so that any capital letter that starts a new word
    (immediately preceded by a word character) is preceded by exactly one space,
    splitting runs of capitals only when followed by lowercase letters.

    For example:
    'hello WorldThis Is a Test' -> 'hello World This Is a Test'
    """
    # Pattern explanation:
    # Look for a position where:
    # - preceded by a word character (\w)
    # - followed by a capital letter ([A-Z])
    # - that is followed by a lowercase letter ([a-z])
    # We insert a space before that capital letter.
    pattern = re.compile(r'(\w)([A-Z](?=[a-z]))')
    # Replace the match by the first group + space + second group
    # This inserts space between a lower or upper word char and a capital letter that starts a lowercase word.
    return pattern.sub(r'\1 \2', text)

