def count_list(collection):
    """
    Count the total number of immediate nested structures inside the top-level input collection.

    Immediate nested structures are elements of the collection that are themselves collections:
    e.g., list, tuple, set, dict, etc.

    Parameters:
        collection (iterable): The top-level input iterable.

    Returns:
        int: The count of immediate nested structures inside the input collection.
    """
    # We consider as "nested structures" any instance of collections.abc.Collection
    # but exclude strings and bytes, since they are iterable but typically not considered collections here.
    import collections.abc

    count = 0
    for elem in collection:
        if isinstance(elem, collections.abc.Collection) and not isinstance(elem, (str, bytes)):
            count += 1
    return count

