def sum_column(data, key):
    """
    Sum the numeric values at the given key/index across all rows in data.

    Parameters:
    - data: a sequence of rows, each supporting indexing by key (string or integer).
    - key: key or index to extract the values to sum.

    Behavior:
    - For each row in data:
      - If the row does not have the key/index, treat value as zero.
      - If the value at key is not numeric (int or float), treat as zero.
    - Return the total sum as a float.

    Example:
    sum_column(
        [{'category': 'A', 'value': 10},
         {'value': 5},
         {'category': 'A', 'value': 'x'},
         {'category': 'B', 'value': 7}],
        'value'
    )  # returns 22.0 (10 + 5 + 0 + 7)
    """
    total = 0.0
    for row in data:
        try:
            val = row[key]
        except (KeyError, IndexError, TypeError):
            val = 0
        if not isinstance(val, (int, float)):
            val = 0
        total += float(val)
    return total

