def lucky_num():
    """
    Generate a list of "lucky numbers" using the sieve process:
    Start with the list of integers from 1 to 100 inclusive.
    Iteratively remove numbers based on the value at the current position:
    - First, remove every 2nd number (because the first lucky number after 1 is 2),
    - Then remove every nth number where n is the next lucky number in the updated list,
    - Continue until the sieve passes beyond the length of the list.

    Returns:
        List[int]: The list of lucky numbers from 1 to 100.
    """
    numbers = list(range(1, 101))
    idx = 1  # Start from the second element (index 1) because lucky numbers start with 2

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # We remove numbers at positions step-1, 2*step-1, ... in zero-based indexing,
        # but after each removal, indices shift, so we remove by reconstructing the list:
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1

    return numbers

