from math import gcd
from typing import List

def get_gcd(arr: List[int]) -> int:
    """
    Compute the gcd of the absolute values of all elements in arr.
    If arr contains only zeros, return 0.
    Otherwise, return the gcd which is strictly positive.
    """
    if not arr:
        raise ValueError("Input list must not be empty")

    # Compute gcd of absolute values
    current_gcd = 0
    for num in arr:
        current_gcd = gcd(current_gcd, abs(num))

    return current_gcd

