def zip_tuples(t1, t2):
    """
    Zip two tuples element-wise up to the length of the longer tuple,
    cycling through the shorter tuple's elements repeatedly.

    Args:
        t1 (tuple): First tuple.
        t2 (tuple): Second tuple.

    Returns:
        tuple: Tuple of pairs formed by pairing elements at matching indices,
               cycling shorter tuple elements as needed.
    """
    max_len = max(len(t1), len(t2))
    return tuple((t1[i % len(t1)], t2[i % len(t2)]) for i in range(max_len))

