def next_smallest_palindrome(n: int) -> int:
    """
    Find the smallest palindrome strictly greater than n.
    For single-digit n from 0 to 8, return n+1.
    For n = 9, return 11.
    For other numbers, find the next palindrome greater than n.
    """

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # Handle single-digit cases explicitly per user answer
    if 0 <= n <= 8:
        return n + 1
    if n == 9:
        return 11

    s = str(n)
    length = len(s)
    half_len = (length + 1) // 2

    # Generate palindrome by mirroring the left half to right
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            # exclude the last char of left when mirroring
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    left = s[:half_len]
    palindrome = make_palindrome(left, odd_length)

    if palindrome > n:
        return palindrome

    # Increment the left half and rebuild palindrome
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # Handle case where incrementing left half increases length (e.g., 999 -> 1000)
    if len(left) > half_len:
        # For example, 999 -> next palindrome is 1001 (length+1)
        return int("1" + ("0" * (length - 1)) + "1")

    palindrome = make_palindrome(left, odd_length)
    return palindrome

