def find_solution(a: int, b: int, n: int):
    """
    Find the first pair of non-negative integers (x, y) satisfying a*x + b*y = n.

    Returns:
        (x, y): tuple of non-negative integers if a solution exists,
        None: if no non-negative integer solution exists.
    """
    # Handle the case when a or b is zero:
    # If a == 0, then b*y = n => y = n/b if b divides n and y >= 0
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    if a == 0:
        if b == 0:
            return None  # already handled above, but keep for clarity
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None

    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None

    # Both a and b are non-zero
    # We want non-negative x, y such that a*x + b*y = n
    # We'll iterate over x from 0 upwards until a*x > n or no solution possible

    # To avoid infinite loops when a or b is negative, define search boundaries carefully.

    # We want x >= 0 and y >= 0.
    # For that:
    # a*x + b*y = n
    # => b*y = n - a*x
    # => y = (n - a*x)/b
    # y must be integer and y >= 0

    # Depending on sign of a and b, the valid range for x may differ.
    # We attempt all x in [0, max_x], where max_x depends on a and n.

    # Determine the range for x:
    # If a > 0, then max_x <= n//a (since x >= 0)
    # If a < 0, then since x >= 0, a*x <= 0, so n - a*x >= n.
    # But y must be >= 0, so (n - a*x)/b >= 0.
    # So for each x >= 0, check if y is integer and y >= 0.

    # Similarly, if b < 0, y >= 0 implies (n - a*x)/b >= 0, so (n - a*x) and b have opposite signs.

    # We'll try x from 0 up to some reasonable limit.
    # Since no limits were specified, let's try up to a max_x determined by n and a and b.

    # Because a and b can be negative, we need to find a proper upper bound for x.
    # We'll try to find all x >= 0 such that y = (n - a*x)/b >= 0 and integer.

    # To avoid infinite loop, let's try all x from 0 up to 10**6.
    # If no solution found, return None.

    MAX_ITER = 10**6

    for x in range(MAX_ITER + 1):
        numerator = n - a * x
        if b == 0:
            # already handled above
            break
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)
        # If a > 0 and a*x > n, no point continuing (since x increasing only increases a*x)
        if a > 0 and a * x > n:
            break
        # If a < 0, increasing x decreases a*x, so no fixed upper bound,
        # but we still limit by MAX_ITER to avoid infinite loops.

    return None

