def next_power_of_2(n: int) -> int:
    # Handle base case
    if n == 1:
        return 1

    # Check if n is a power of two
    if (n & (n - 1)) == 0:
        return n

    # n is not a power of two, find the smallest power of two greater than n
    power = 1
    while power <= n:
        power <<= 1
    return power

