def decode_list(encoded):
    """
    Decodes a run-length encoded list into the uncompressed list.

    The encoded list is expected to be in the format:
    [count1, value1, count2, value2, ..., countN, valueN]

    Returns a flat list where each value is repeated count times.

    Example:
    decode_list([1, 3, 2, 4]) -> [3, 4, 4]
    """
    if len(encoded) % 2 != 0:
        raise ValueError("Encoded list length must be even")

    decoded = []
    for i in range(0, len(encoded), 2):
        count = encoded[i]
        value = encoded[i + 1]
        decoded.extend([value] * count)
    return decoded

