def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    if not d:
        return 1
    max_depth = 0
    for value in d.values():
        # Only consider nested dictionaries directly inside the current dict
        if isinstance(value, dict):
            depth = dict_depth(value)
            if depth > max_depth:
                max_depth = depth
        # Lists and tuples do not add to depth and are not traversed
    return 1 + max_depth

