from typing import List, Any

def remove_column(matrix: List[List[Any]], col_idx: int) -> List[List[Any]]:
    """
    Remove the element at index `col_idx` from each row of `matrix`.

    Each row can have different lengths. If any row does not have an element
    at `col_idx`, an IndexError is raised.

    Args:
        matrix: A non-empty list of lists (rows), each possibly different length.
        col_idx: The index of the column to remove from each row.

    Returns:
        A new list of lists with the specified column removed.
    """
    result = []
    for row in matrix:
