def min_flip_to_make_string_alternate(s: str) -> int:
    """
    Compute the minimum number of bit flips needed to make the binary string s strictly alternate,
    by comparing the cost of making it start with '0' and start with '1'.
    Return the smaller of the two costs.
    """
    flips_start_0 = 0
    flips_start_1 = 0

    for i, ch in enumerate(s):
        expected_0 = '0' if i % 2 == 0 else '1'
        expected_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_0:
            flips_start_0 += 1
        if ch != expected_1:
            flips_start_1 += 1

    return min(flips_start_0, flips_start_1)

