def smallest_missing(arr, low, high):
    """
    Finds the smallest missing non-negative integer in the subarray arr[low:high+1],
    assuming arr is sorted with distinct non-negative integers.

    The expected sequence is arr[i] == i, regardless of arr[low].
    So we look for the smallest integer >= 0 that does not appear in arr[low:high+1].

    If no integer is missing in [0, ..., arr[high]], return arr[high] + 1.

    Parameters:
    arr (List[int]): sorted list of distinct non-negative integers
    low (int): start index (inclusive)
    high (int): end index (inclusive)

    Returns:
    int: smallest missing non-negative integer in arr[low:high+1]
    """
    # We'll search for the smallest missing integer in arr[low:high+1]
    # since arr is sorted and distinct, we can use binary search
    # to find the first index i in [low, high] where arr[i] != i.

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1

    # After the loop, left is the smallest index where arr[left] != left or left == high+1
    # So the smallest missing integer is left (if left in [low, high]) or arr[high] + 1

    # But the missing integer must be non-negative, and since arr is sorted distinct non-negative,
    # the missing integer is left if left <= high, else arr[high] + 1

    if left <= high:
        return left
    else:
        return arr[high] + 1

