def add_string(lst, fmt):
    """
    Prepend each element in lst with the given format string fmt.

    The format string fmt must contain at most one substitution slot,
    i.e., at most one pair of curly braces {} for formatting.

    For each element in lst, convert it to string and substitute it into fmt.

    Args:
        lst (list): List of elements to format.
        fmt (str): Format string containing at most one substitution slot.

    Returns:
        list of str: List of formatted strings.

    Raises:
        ValueError: If fmt contains more than one substitution slot.
    """
    # Count substitution slots in fmt
    # We'll count unescaped {} pairs that are substitution slots.
    # To do this, we can use string.Formatter.parse()
    import string

    formatter = string.Formatter()
    slots = 0
    for _, field_name, _, _ in formatter.parse(fmt):
        if field_name is not None:
            slots += 1
    if slots > 1:
        raise ValueError("Format string must contain at most one substitution slot.")

    result = []
    for e in lst:
        if slots == 1:
            # substitute element converted to string
            result.append(fmt.format(str(e)))
        else:
            # no substitution slot - just use the format string as is
            result.append(fmt)
    return result

