def find_Max(arr):
    if not arr:
        return None

    left, right = 0, len(arr) - 1

    # If the array is not rotated (sorted ascending), the max is the last element
    if arr[left] < arr[right]:
        return arr[right]

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is the maximum element
        if mid < right and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > left and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which side to go
        if arr[mid] >= arr[left]:
            # Left part is sorted, max must be in right part
            left = mid + 1
        else:
            # Right part is sorted, max must be in left part
            right = mid - 1

    return None  # fallback, ideally never reached
