import re

def text_match(s):
    # Pattern explanation:
    # a       -> literal 'a'
    # b*      -> zero or more 'b's
    # (?!b)   -> negative lookahead to ensure no 'b' immediately follows
    pattern = r'a b* (?!b)'.replace(' ', '')
    if re.search(pattern, s):
