from typing import List, Union

def sum_column(lst: List[List[Union[int, float]]], col_idx: int) -> Union[int, float]:
    """
    Sums the specified column (col_idx) across all rows in lst.
    Missing values in shorter rows are treated as zero.

    Args:
        lst: List of lists of numbers (rows).
        col_idx: Index of the column to sum.

    Returns:
        The sum of the specified column as a number (int or float).
        Returns 0 if lst is empty or if col_idx is out of bounds (i.e., no rows have that column).
    """
    total = 0
    for row in lst:
        if col_idx < len(row):
            total += row[col_idx]
        else:
            total += 0  # Explicitly showing missing values treated as zero
    return total

