def is_triangleexists(a1, a2, a3):
    """
    Check if three angles can form a triangle with positive area.

    Args:
        a1 (int or float): First angle in degrees.
        a2 (int or float): Second angle in degrees.
        a3 (int or float): Third angle in degrees.

    Returns:
        bool: True if the three angles form a triangle with positive area,
              False otherwise.
    """
    # All angles must be positive
    if a1 <= 0 or a2 <= 0 or a3 <= 0:
        return False
    # The sum of the three angles must be exactly 180 degrees
    if a1 + a2 + a3 != 180:
        return False
    return True

