def check_Even_Parity(n: int) -> bool:
    """
    Check if the integer n has even parity, i.e., an even number of set bits (1s) in its binary representation.

    Args:
        n (int): The integer to check.

    Returns:
        bool: True if n has even parity, False otherwise.
    """
    # Count the number of set bits in n
    count_ones = bin(n).count('1')
    # Return True if count_ones is even
    return count_ones % 2 == 0
