def lucky_num(n):
    """
    Return the first n lucky numbers in the traditional sequence.

    Lucky numbers are generated by the sieve of lucky numbers method:
    Start with the list of odd numbers starting from 1: [1, 3, 5, 7, 9, 11, ...]
    The second element in the list (3) is the first "step" to remove every 3rd number from the list.
    Then take the next surviving number after the step (7), remove every 7th number, and so forth,
    until the list is long enough to contain n lucky numbers.

    Examples:
    lucky_num(10) -> [1, 3, 7, 9, 13, 15, 21, 25, 31, 33]
    lucky_num(5)  -> [1, 3, 7, 9, 13]
    lucky_num(8)  -> [1, 3, 7, 9, 13, 15, 21, 25]
    """
    if n < 1:
        return []

    # Start with odd numbers starting from 1,
    # generate more than enough numbers to safely sieve n lucky numbers.
    # We choose initial size arbitrarily large to ensure enough lucky numbers remain after sieving.
    size = 2 * n * n  # heuristic: can be adjusted if needed

    numbers = list(range(1, size * 2, 2))  # odd numbers starting at 1

    idx = 1  # start with second element (index 1), which is the first step value (3)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number (1-based counting)
        # The indexing for removal is zero-based, so remove indices: step-1, 2*step-1, 3*step-1, ...
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # We have enough lucky numbers to return
            break

    return numbers[:n]

