def compute_Last_Digit(A, B):
    # If A == B, return 1
    if A == B:
        return 1

    # If the range length is 5 or more, return 0
    if B - A >= 5:
        return 0

    # Compute the product of all integers from A+1 to B inclusive
    product = 1
    for x in range(A + 1, B + 1):
        product *= x

    # Return the last digit of the absolute value of the product
    return abs(product) % 10
