def dif_Square(n: int) -> bool:
    """
    Returns True if n can be expressed as a difference of two squares,
    i.e., n = a^2 - b^2 for some integers a, b.
    Returns False otherwise.

    According to the known number theory result:
    An integer n can be expressed as difference of two squares
    if and only if n is NOT congruent to 2 modulo 4.

    Examples:
    dif_Square(6) -> False (6 % 4 == 2)
    dif_Square(7) -> True  (7 % 4 == 3)
    dif_Square(8) -> True  (8 % 4 == 0)
    dif_Square(3) -> True  (3 % 4 == 3)
    dif_Square(2) -> False (2 % 4 == 2)
    """
    return n % 4 != 2
