def Find_Min_Length(lst):
    """
    Finds the length of the shortest sublist if the input list is a list of lists.
    Otherwise, returns the length of the entire list.
    Returns 0 if the input list is empty.

    Args:
        lst (list): Input list, which can be flat or contain sublists.

    Returns:
        int: Length of the shortest sublist or the whole list if not a list of lists, or 0 if empty.
    """
    if not lst:
        return 0

    # Check if the list is a list of lists (all elements are lists)
    if all(isinstance(el, list) for el in lst):
        if not lst:  # redundant, but safe if all are lists and empty
            return 0
        # Find the length of the shortest sublist
        return min(len(sublist) for sublist in lst)
    else:
        # Not a list of lists; return the length of the whole list
        return len(lst)
