def next_smallest_palindrome(num: int) -> int:
    """
    Find the smallest palindrome integer strictly greater than the input integer num.
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    candidate = num + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1

