def find_solution(a, b, n):
    """
    Find the first valid solution (x, y) with x >= 0 for the equation a*x + b*y = n.
    Returns a 4-element tuple: ('x = ', x, ', y = ', y) if a solution exists,
    otherwise returns None.
    """
    # Scan x from 0 upwards until a solution is found or no solution is possible
    # Since y must be integer, check if (n - a*x) is divisible by b

    # If b == 0, then equation is a*x = n, y can be anything, but we want an integer y.
    # In that case, if n - a*x == 0, then y can be 0.
    # But since we want the first non-negative x, we just check x values.

    x = 0
    while True:
        lhs = a * x
        remainder = n - lhs
        if b == 0:
            # If b=0, only solution if remainder == 0
            if remainder == 0:
                # y can be any integer, return y=0
                return ('x = ', x, ', y = ', 0)
            else:
                # No solution for this x, try next x
                x += 1
                # To avoid infinite loop if a=0 and b=0:
                if a == 0:
                    break
                continue
        # Check if remainder divisible by b
        if b != 0 and remainder % b == 0:
            y = remainder // b
            # Found valid solution
            return ('x = ', x, ', y = ', y)
        # To avoid infinite loop, if a=0 and b != 0:
        # If a=0, then lhs = 0, remainder = n always same, so if no solution at x=0,
        # no solution at any x>0 either.
        if a == 0:
            break
        x += 1

    # No solution found
    return None

