def find_exponentio(base_exp):
    """
    Perform element-wise exponentiation where both inputs are tuples of the same length.

    Args:
        base_exp (tuple): A tuple containing exactly two tuples of the same length.
                          The first tuple represents the bases,
                          the second tuple represents the exponents.

    Returns:
        tuple: A tuple where each element is base[i] ** exponent[i].

    Raises:
        TypeError: If input is not a tuple of two tuples, or elements are not numeric.
        ValueError: If the two tuples are not of the same length.
    """
    if (
        not isinstance(base_exp, tuple) or
        len(base_exp) != 2 or
        not all(isinstance(t, tuple) for t in base_exp)
    ):
        raise TypeError("Input must be a tuple of two tuples (bases, exponents).")

    bases, exponents = base_exp

    if len(bases) != len(exponents):
        raise ValueError("Bases and exponents tuples must be of the same length.")

    def is_number(x):
        return isinstance(x, (int, float))

    if not all(is_number(b) for b in bases):
        raise TypeError("All base elements must be int or float.")
    if not all(is_number(e) for e in exponents):
        raise TypeError("All exponent elements must be int or float.")

    return tuple(b ** e for b, e in zip(bases, exponents))

