def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Calculate the total number of sequences of length n
    where each element is chosen from a range of m elements.

    Args:
        m (int): The number of possible elements for each position.
        n (int): The length of the sequence.

    Returns:
        int: The total number of possible sequences.
    """
