def text_match_two_three(text: str, pattern: str) -> bool:
    """
    Returns True if text contains a substring where pattern occurs exactly 2 or exactly 3 
    times consecutively and contiguously, with no additional immediate repetition before or after.
    Otherwise returns False.

    Example:
    text_match_two_three('abcabcxabc', 'abc') -> True
    (because 'abcabc' is pattern repeated exactly twice contiguously)

    """
    plen = len(pattern)
    tlen = len(text)

    # We look for occurrences where pattern repeats exactly 2 or 3 times consecutively,
    # with no additional immediate repetition before or after.

    for start in range(tlen):
        # Check substring starting at start for 2 or 3 consecutive repeats
        for count in (2, 3):
            end = start + plen * count
            if end > tlen:
                continue
            segment = text[start:end]
            if segment == pattern * count:
                # Check no immediate repetition before
                before_index = start - plen
                if before_index >= 0:
                    if text[before_index:start] == pattern:
                        continue  # pattern repeats before segment, so not exactly 2 or 3
                # Check no immediate repetition after
                after_index = end
                if after_index + plen <= tlen:
                    if text[after_index:after_index+plen] == pattern:
                        continue  # pattern repeats after segment
                # If passed, found valid substring
                return True
    return False

