def remove_column(data, column):
    """
    Remove all dictionary entries with the specified string key recursively,
    or remove element at the specified integer index from every list recursively.

    Args:
        data: nested structure of dicts, lists, or other types.
        column: string key to remove from all dicts, or integer index to remove from all lists.

    Returns:
        A new nested data structure matching the input's shape but without the specified key or index.
    """
    if isinstance(column, str):
        # Remove dictionary entries with this key
        if isinstance(data, dict):
            return {k: remove_column(v, column) for k, v in data.items() if k != column}
        elif isinstance(data, list):
            return [remove_column(item, column) for item in data]
        else:
            return data
    elif isinstance(column, int):
        # Remove element at this index from every list
        if isinstance(data, dict):
            return {k: remove_column(v, column) for k, v in data.items()}
        elif isinstance(data, list):
            # Remove element at index if valid, else keep list as is
            new_list = []
            for i, item in enumerate(data):
                if i == column:
                    continue  # skip this element
                new_list.append(remove_column(item, column))
            return new_list
        else:
            return data
    else:
        # If column is neither str nor int, no removal, just recurse
        if isinstance(data, dict):
            return {k: remove_column(v, column) for k, v in data.items()}
        elif isinstance(data, list):
            return [remove_column(item, column) for item in data]
        else:
            return data

