def min_flip_to_make_string_alternate(s: str) -> int:
    """
    Compute the minimal number of flips required to convert the input binary string into an alternating binary string,
    starting with either '0' or '1'.

    Args:
        s (str): Input binary string (can be empty).

    Returns:
        int: Minimal number of flips required.
    """
    def flips_to_match(start_char: str) -> int:
        flips = 0
        expected = start_char
        for ch in s:
            if ch != expected:
                flips += 1
            # flip expected character for next position
            expected = '1' if expected == '0' else '0'
        return flips

    # Check both starting possibilities and return the minimal flips
    return min(flips_to_match('0'), flips_to_match('1'))

