def repeat_tuples(data):
    """
    Repeat the input data according to the clarified behavior:

    - If the input is a list of tuples, each tuple contains numeric elements to be summed.
      For each tuple in the list:
        - If the sum of its elements is positive, include that tuple repeated exactly that many times.
        - Otherwise, omit it.
      Return a list of tuples, ordered by input sequence with each tuple repeated consecutively according to its positive sum.

    - If the input is a single tuple:
      Repeat that tuple sum(tuple) times if the sum is positive, otherwise return an empty list.

    Examples:
    repeat_tuples([(1, 2), (3, 0), (0, 0)])
    -> [(1, 2), (1, 2), (1, 2), (3, 0), (3, 0), (3, 0)]

    repeat_tuples((2, 3))
    -> [(2, 3), (2, 3), (2, 3), (2, 3), (2, 3)]

    repeat_tuples((0, 0))
    -> []
    """
    # Check if input is a single tuple or a list of tuples
    if isinstance(data, tuple):
        s = sum(data)
        return [data] * s if s > 0 else []
    elif isinstance(data, list):
        result = []
        for tup in data:
            s = sum(tup)
            if s > 0:
                result.extend([tup] * s)
        return result
    else:
        # If input is neither tuple nor list, return empty list as no behavior defined
        return []

