def smallest_missing(arr):
    """
    Find the smallest missing non-negative integer starting from 0 in a sorted array.

    The array is expected to be sorted and to have elements matching their indices until the missing value.
    For example:
    - smallest_missing([0, 1, 2, 4]) returns 3
    - smallest_missing([1, 2, 3]) returns 0
    - smallest_missing([0, 1, 2, 3]) returns 4

    Parameters:
        arr (List[int]): Sorted list of integers (may include negative numbers).

    Returns:
        int: The smallest missing non-negative integer starting from 0.
    """
    for i, val in enumerate(arr):
        if val != i:
            return i
    return len(arr)

