def permute_string(s: str) -> list[str]:
    if len(s) <= 1:
        return [s]

    # Recursively get permutations of the suffix (all except first character)
    suffix_perms = permute_string(s[1:])
    first_char = s[0]
    result = []

    for perm in suffix_perms:
        # Insert first_char into perm at all positions, but:
        # Build permutations by inserting at rightmost position moving leftward,
        # but append them in left-to-right order of insertion positions.
        # So positions go from rightmost index to 0, but results appended from 0 to rightmost.

        # Collect all insertions for this perm in order left to right
        insertions = []
        for i in range(len(perm), -1, -1):
            new_perm = perm[:i] + first_char + perm[i:]
            insertions.insert(0, new_perm)  # insert at front to reverse order

        # Now extend result by these insertions in left-to-right order
        result.extend(insertions)

    return result

