def find_Max(arr):
    """
    Finds and returns the maximum element in the input list `arr`.
    If the list is empty, returns None.

    Parameters:
    arr (list): A list of comparable elements.

    Returns:
    The maximum element in the list or None if the list is empty.
    """
    if not arr:
        return None
    max_val = arr[0]
    for item in arr[1:]:
        if item > max_val:
            max_val = item
    return max_val
