from math import comb

def sum_Of_product(n: int) -> int:
    """
    Compute the sum of products of binomial coefficients:
    sum_{i=0}^{n-1} C(n, i) * C(n, i+1)

    Args:
        n (int): The integer n for binomial coefficients.

    Returns:
