def reverse_Array_Upto_K(arr, k):
    """
    Return a new list with the first k elements reversed.
    If k <= 0, return a copy of arr unchanged.
    If k > len(arr), reverse the entire arr.
    The original arr is not modified.
    """
    if k <= 0:
        return arr[:]
    if k > len(arr):
        k = len(arr)
    return arr[:k][::-1] + arr[k:]
