def filter_data(data: dict, threshold1: float, threshold2: float) -> dict:
    """
    Filters a dictionary whose values are 2-item tuples, returning a new dictionary
    containing only entries where the first tuple element is at least threshold1
    and the second tuple element is at least threshold2.

    :param data: Dictionary with values as 2-item tuples of numbers.
    :param threshold1: Numeric threshold for the first element of the tuple.
    :param threshold2: Numeric threshold for the second element of the tuple.
    :return: Filtered dictionary meeting the threshold criteria.
    """
    return {
        key: value
        for key, value in data.items()
        if value[0] >= threshold1 and value[1] >= threshold2
    }

