def capital_words_spaces(s: str) -> str:
    if not s:
        return s

    result = [s[0]]
    for i in range(1, len(s)):
        curr = s[i]
        prev = s[i - 1]

        # Insert space if current char is uppercase and:
        # - previous char is lowercase, or
        # - previous char is uppercase but next char exists and is lowercase (start of a new word)
        if curr.isupper():
            if prev.islower():
                result.append(' ')
            elif prev.isupper():
                if i + 1 < len(s) and s[i + 1].islower():
                    result.append(' ')
        result.append(curr)

    return ''.join(result)

