def substract_elements(t1, t2):
    """
    Subtract elements of two tuples of tuples element-wise within each inner tuple.

    Args:
        t1 (tuple of tuples): First tuple containing tuples of numbers (ints or floats).
        t2 (tuple of tuples): Second tuple containing tuples of numbers (ints or floats).

    Returns:
        tuple of tuples: Result of element-wise subtraction (t1 - t2) for each inner tuple.

    Raises:
        ValueError: If the outer tuples do not have the same length, or
                    if any corresponding inner tuples do not have the same length.
    """
    if len(t1) != len(t2):
        raise ValueError("Outer tuples must have the same length.")

    result = []
    for inner1, inner2 in zip(t1, t2):
        if len(inner1) != len(inner2):
            raise ValueError("Inner tuples must have the same length.")
        inner_result = tuple(a - b for a, b in zip(inner1, inner2))
        result.append(inner_result)
    return tuple(result)

