def dif_Square(n: int) -> bool:
    if n == 0:
        return True

    abs_n = abs(n)
    # Iterate over possible factor pairs (x, y) such that x * y = abs_n
    # Only need to check up to sqrt(abs_n)
    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check if x and y have the same parity
            if (x % 2) == (y % 2):
                return True
    return False
