def next_smallest_palindrome(num: int) -> int | None:
    """
    Find the largest palindrome integer strictly less than `num`.
    Return None if no such palindrome exists (e.g., if num <= 1).

    Examples:
    next_smallest_palindrome(10) -> 9
    next_smallest_palindrome(123) -> 121
    next_smallest_palindrome(1) -> None
    next_smallest_palindrome(1000) -> 999
    """
    if num <= 1:
        return None

    # Helper function to check palindrome
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    candidate = num - 1
    while candidate >= 0:
        if is_palindrome(candidate):
            return candidate
        candidate -= 1

    return None

