def find_solution(a: int, b: int, n: int):
    """
    Find one nonnegative integer solution (x, y) to the equation a*x + b*y = n,
    where a, b, n are integers, a and b not both zero.
    Return (x, y) with both x, y >= 0 and x minimal, or None if no solution exists.
    """
    # Handle trivial cases
    if a == 0 and b == 0:
        # Equation 0*x + 0*y = n has solution only if n == 0
        return (0, 0) if n == 0 else None

    # Extended Euclidean algorithm to find x0, y0 with a*x0 + b*y0 = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            gcd, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (gcd, x, y)

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % gcd != 0:
        return None  # No solution

    # Scale the particular solution x0, y0 to the equation a*x + b*y = n
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust signs depending on sign of a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)
    # We want x >= 0 and y >= 0, and x minimal nonnegative integer

    # Coefficients for k
    k_b = b // gcd
    k_a = a // gcd

    # Find k so that x >= 0:
    # x0 + k*k_b >= 0  =>  k >= -x0 / k_b  if k_b != 0
    # Find k so that y >= 0:
    # y0 - k*k_a >= 0  =>  k <= y0 / k_a  if k_a != 0

    # k must be integer

    # To find feasible k values, consider the constraints:
    # If k_b == 0, x = x0 constant, check if x0 >= 0
    # If k_a == 0, y = y0 constant, check if y0 >= 0

    # Compute bounds on k:
    import math

    # Handle k_b == 0 (b == 0)
    if k_b == 0:
        # x = x0 fixed
        if x0 < 0:
            return None
        # y = y0 - k*k_a, y >= 0 => k <= y0 / k_a if k_a != 0
        if k_a == 0:
            # y = y0 constant
            if y0 < 0:
                return None
            else:
                return (x0, y0)
        else:
            # k <= y0 / k_a if k_a > 0, or k >= y0 / k_a if k_a < 0
            # Try to find any integer k satisfying y >= 0
            if k_a > 0:
                max_k = y0 // k_a
                # We want k <= max_k; try k = max_k
                y = y0 - max_k * k_a
                if y < 0:
                    return None
                return (x0, y)
            else:
                # k_a < 0
                min_k = math.ceil(y0 / k_a)
                # k >= min_k, try k = min_k
                y = y0 - min_k * k_a
                if y < 0:
                    return None
                return (x0, y)

    # Handle k_a == 0 (a == 0)
    if k_a == 0:
        # y = y0 fixed
        if y0 < 0:
            return None
        # x = x0 + k*k_b, x >= 0 => k >= -x0 / k_b if k_b != 0
        if k_b == 0:
            # x = x0 constant
            if x0 < 0:
                return None
            else:
                return (x0, y0)
        else:
            if k_b > 0:
                min_k = math.ceil(-x0 / k_b)
                x = x0 + min_k * k_b
                if x < 0:
                    return None
                return (x, y0)
            else:
                max_k = math.floor(-x0 / k_b)
                x = x0 + max_k * k_b
                if x < 0:
                    return None
                return (x, y0)

    # Both k_a and k_b nonzero

    # x >= 0 => k >= ceil(-x0 / k_b) if k_b > 0
    #           k <= floor(-x0 / k_b) if k_b < 0
    if k_b > 0:
        k_min_x = math.ceil(-x0 / k_b)
    else:
        k_min_x = -math.inf
    if k_b < 0:
        k_max_x = math.floor(-x0 / k_b)
    else:
        k_max_x = math.inf

    # y >= 0 => k <= floor(y0 / k_a) if k_a > 0
    #           k >= ceil(y0 / k_a) if k_a < 0
    if k_a > 0:
        k_max_y = math.floor(y0 / k_a)
    else:
        k_max_y = math.inf
    if k_a < 0:
        k_min_y = math.ceil(y0 / k_a)
    else:
        k_min_y = -math.inf

    # Combine bounds for k:
    k_min = max(k_min_x, k_min_y)
    k_max = min(k_max_x, k_max_y)

    if k_min > k_max:
        return None  # no integer k satisfies both constraints

    # Among all k in [k_min, k_max], choose k that minimizes x = x0 + k*k_b with x >= 0
    # Since k_b can be positive or negative, check endpoints

    # Because x is linear in k and we want minimal nonnegative x,
    # and k in [k_min, k_max], check k_min and k_min+1 if possible for minimal x

    # But only integers in [k_min, k_max]
    # k_min and k_max can be -inf or inf, but they are bounded by constraints above.

    # We can scan k in integer range [k_min, k_max] and pick minimal x
    # But that could be large range, so do minimal checks:

    # k_min and k_max are finite ints or infinite
    # Replace infinite with some large bounds
    INF = 10**18
    if k_min == -math.inf:
        k_min = -INF
    if k_max == math.inf:
        k_max = INF

    # Because we want minimal x >=0, and x = x0 + k*k_b:
    # If k_b > 0, x increases with k, so minimal x at smallest k in range
    # If k_b < 0, x decreases with k, so minimal x at largest k in range
    # So pick k accordingly

    if k_b > 0:
        candidate_k = k_min
    else:
        candidate_k = k_max

    # Ensure candidate_k is int and in range
    candidate_k = int(candidate_k)
    if candidate_k < k_min:
        candidate_k = int(k_min)
    if candidate_k > k_max:
        candidate_k = int(k_max)

    x = x0 + candidate_k * k_b
    y = y0 - candidate_k * k_a

    if x < 0 or y < 0:
        # try the other bound in case candidate_k chosen incorrectly
        other_k = k_max if candidate_k == k_min else k_min
        other_k = int(other_k)
        x = x0 + other_k * k_b
        y = y0 - other_k * k_a
        if x < 0 or y < 0:
            return None
        else:
            return (x, y)
    else:
        return (x, y)

