def decode_list(encoded):
    """
    Decode a run-length encoded list.

    Parameters:
    encoded (list): A list containing either standalone literal values (appearing once)
                    or 2-item lists/tuples of the form [count, value] representing run-length encoding.

    Returns:
    list: The decoded list with values repeated as specified.

    Raises:
    ValueError: If any pair is not length two or count is not a non-negative integer.
    """
    decoded = []
    for item in encoded:
        # If item is a list or tuple of length 2, treat as [count, value]
        if isinstance(item, (list, tuple)):
            if len(item) != 2:
                raise ValueError(f"Run-length pair must have exactly two elements, got {item!r}")
            count, value = item
            if not (isinstance(count, int) and count >= 0):
                raise ValueError(f"Count must be a non-negative integer, got {count!r} in pair {item!r}")
            decoded.extend([value] * count)
        else:
            # Otherwise, treat as a single literal value (count=1)
            decoded.append(item)
    return decoded

