def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i starting with element x
    # Since the first element can be any from 1 to m,
    # for i=1, dp[1][x] = 1 for all x in [1..m]

    if n == 1:
        return m  # all single elements from 1 to m are valid sequences

    dp = [ [0] * (m + 1) for _ in range(n + 1) ]

    # Initialize for sequences of length 1
    for x in range(1, m + 1):
        dp[1][x] = 1

    for length in range(2, n + 1):
        # For each previous element prev, find all next elements x:
        # x >= 2 * prev and x <= m
        # For efficiency, we can precompute prefix sums or just do direct calculation
        # Because m can be large, we do direct iteration for clarity.

        # To optimize, for each length, we can build prefix sums over dp[length-1]
        prefix_sums = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sums[x] = prefix_sums[x - 1] + dp[length - 1][x]

        for x in range(1, m + 1):
            # The element at position length is x
            # So the previous element prev must satisfy:
            # prev <= x / 2 (since x >= 2 * prev => prev <= x/2)
            max_prev = x // 2
            if max_prev >= 1:
                # Sum dp[length-1][1..max_prev]
                dp[length][x] = prefix_sums[max_prev]
            else:
                dp[length][x] = 0

    # Sum all sequences of length n starting with any valid first element
    # Actually dp[n][x] counts number of sequences of length n ending with x
    # Because dp[i][x] is defined as sequences of length i ending with x.
    # So total sequences = sum over x in [1..m] dp[n][x]
    return sum(dp[n][1:m+1])

