def even_binomial_Coeff_Sum(n: int) -> int:
    """
    Returns the sum of binomial coefficients C(n, k) for all even k from 0 through n inclusive.

    According to the clarification:
    - For n = 0, returns 1.
    - For n > 0, returns 2^(n-1).

    Parameters:
    n (int): non-negative integer representing the binomial coefficient row.

    Returns:
    int: sum of even-index binomial coefficients in row n.
    """
    if n == 0:
        return 1
    return 2 ** (n - 1)
