def smallest_missing(arr):
    if not arr:
        return 0
    # If first element is greater than 0, 0 is missing
    if arr[0] > 0:
        return 0

    # Binary search for the smallest missing element
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        # Check if the value matches its index
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1

    # left is now the smallest missing index/value
    return left

