def find_remainder(arr, length, n):
    """
    Compute the product of the first 'length' elements in 'arr' modulo 'n'.

    Parameters:
    arr (list of int): The list of integers.
    length (int): Number of elements from arr to consider.
    n (int): The divisor.

    Returns:
    int: The remainder of the product modulo n.

    Raises:
    ValueError: If n is zero or length is negative or length is greater than len(arr).

    Behavior:
    - If length is 0, return 1 % n.
    - Multiply the first 'length' elements modulo n and return the remainder.
    """
    if n == 0:
        raise ValueError("Divisor n cannot be zero")
    if length < 0:
        raise ValueError("Length cannot be negative")
    if length > len(arr):
        raise ValueError("Length cannot be greater than the array size")

    product = 1 % n  # ensures correct behavior if n == 1
    for i in range(length):
        product = (product * arr[i]) % n
    return product

