def find_Max(arr, low, high):
    # If the array is not rotated (sorted ascending), the maximum is the last element
    if arr[low] <= arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2

        # Check if mid is pivot point (greater than its next element)
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]

        # Check if mid-1 is pivot point
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide whether to go left or right
        if arr[mid] >= arr[low]:
            # Left side is sorted, pivot must be in right side
            low = mid + 1
        else:
            # Right side is sorted, pivot must be in left side
            high = mid - 1

    # Fallback (should not be reached for valid input)
    return arr[low]
