def reverse_Array_Upto_K(arr, k):
    """
    Reverse the elements of arr from the start up to and including the k-th element (1-indexed).
    k is clamped to the range [1, len(arr)].

    Parameters:
        arr (list): The input list to reverse part of.
        k (int): 1-indexed position up to which to reverse.

    Returns:
        list: A new list with the first k elements reversed and the rest unchanged.
    """
    n = len(arr)
    # Clamp k to [1, n]
    k = max(1, min(k, n))

    return arr[:k][::-1] + arr[k:]
