import re

def text_match(text: str) -> str:
    """
    Returns "Found a match!" if the input string contains the substring 'a' followed by zero or more 'b's,
    otherwise returns "Not matched!".

    Examples:
    text_match("a") -> "Found a match!"
    text_match("ab") -> "Found a match!"
    text_match("abbb") -> "Found a match!"
    text_match("ba") -> "Found a match!"
    text_match("b") -> "Not matched!"
    """
