def filter_data(data):
    """
    Filters the input dictionary of students to include only 'height' and 'width' attributes.

    Args:
        data (dict): A dictionary mapping student identifiers to dictionaries of attributes.

    Returns:
        dict: A dictionary mapping student identifiers to dictionaries containing only the
              'height' and 'width' keys if they exist.
