def substract_elements(t1, t2):
    """
    Subtract corresponding elements of two nested tuples.
    Each element is either an int or a nested tuple of ints.
    The subtraction is done element-wise recursively.
    If the structure of t1 and t2 differ, raise a ValueError.
    Returns a nested tuple matching the input structure with subtracted values.

    Args:
        t1 (tuple or int): First nested tuple or int.
        t2 (tuple or int): Second nested tuple or int.

    Returns:
        tuple or int: Element-wise subtraction result.

    Raises:
        ValueError: If t1 and t2 have different structures.
    """
    # If both are ints, subtract directly
    if isinstance(t1, int) and isinstance(t2, int):
        return t1 - t2

    # If both are tuples, subtract element-wise recursively
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        if len(t1) != len(t2):
            raise ValueError("Input tuples have different lengths")
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))

    # If one is int and the other is tuple, structure mismatch
    raise ValueError("Input tuples have different structures")

