def lucky_num(n):
    if n <= 0:
        return []
    # Initial list: odd numbers from 1 to 49999
    numbers = list(range(1, 50000, 2))

    # Perform the sieve until we have at least n lucky numbers
    idx = 1  # start from second element (index 1) which is the first sieve step k
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number (1-based indexing)
        numbers = [num for i, num in enumerate(numbers, 1) if i % step != 0]
        idx += 1

    # If we still don't have enough lucky numbers, continue sieving until we do
    while len(numbers) < n and idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        numbers = [num for i, num in enumerate(numbers, 1) if i % step != 0]
        idx += 1

    return numbers[:n]

