def get_noOfways(n, m):
    # Return 0 if board width is not 2 or length is non-positive
    if m != 2 or n <= 0:
        return 0

    # Base cases
    if n == 1:
        return 1
    if n == 2:
        return 2

    # dp[i] represents the number of ways to tile a 2 x i board
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2

    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[n]
