def compute_Last_Digit(a: int, b: int) -> int | None:
    if a > b:
        return None
    # The value to consider is factorial(b)/factorial(a) = product of (a+1) to b
    # Compute the last digit of that product.
    product_last_digit = 1
    for num in range(a + 1, b + 1):
        product_last_digit = (product_last_digit * (num % 10)) % 10
    return product_last_digit
