def dif_Square(n: int) -> bool:
    """
    Check if the integer n can be represented as the difference of squares of two integers,
    i.e. n = a^2 - b^2 for some integers a, b.

    Equivalently, n = (a+b)(a-b) = x*y where x = a+b and y = a-b are integers of the same parity.

    Return True if such integers exist, False otherwise.
    """
    # n = a^2 - b^2 = (a+b)(a-b) = x*y
    # Both x and y must be integers, same parity, and satisfy (x+y)/2 = a, (x-y)/2 = b integers.
    # So x and y must have the same parity => (x + y) even and (x - y) even.
    # This means x and y are both even or both odd.

    # Special case: n=0 => 0 = a^2 - a^2, always True
    if n == 0:
        return True

    # Iterate over all factor pairs (x,y) of n: x*y = n
    # Check if x and y have the same parity.
    # We only need to check positive divisors, negative pairs are symmetric.
    # But since a,b can be any integers, negative factors also possible.
    # So consider both positive and negative factors.

    # To find factor pairs, iterate over all divisors d of abs(n)
    abs_n = abs(n)
    for d in range(1, int(abs_n**0.5) + 1):
        if abs_n % d == 0:
            x_candidates = [d, -d]
            y_candidates = [abs_n // d, -(abs_n // d)]
            for x in x_candidates:
                for y in y_candidates:
                    # Check if x*y == n
                    if x * y == n:
                        # Check parity
                        if (x % 2 == y % 2):
                            # (x+y) and (x-y) are even, so (x+y)//2 and (x-y)//2 are integers
                            # So a = (x+y)//2, b = (x-y)//2 are integers
                            return True
    return False
dif_square = dif_Square

