def zip_tuples(t1, t2):
    """
    Pairs each element of the first tuple t1 with elements from the second tuple t2,
    cycling through t2 repeatedly until all elements of t1 are paired.

    Returns a list of 2-element tuples.
    """
    if not t2:
        raise ValueError("Second tuple must not be empty to cycle through its elements.")

    result = []
    len_t2 = len(t2)
    for i, elem in enumerate(t1):
        result.append((elem, t2[i % len_t2]))
    return result

