def find_solution(a, b, n):
    """
    Find one particular integer solution (x, y) to the equation:
        a*x + b*y = n
    such that x is the smallest non-negative integer (x >= 0) starting from 0 upwards,
    or return 'No solution' if no such solution exists.

    Returns:
        A tuple: ('x = ', x, ', y = ', y) if solution found,
        or 'No solution' if none exists.
    """
    def extended_gcd(aa, bb):
        # Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(abs(a), abs(b))

    # No solution if n not divisible by gcd
    if n % g != 0:
        return 'No solution'

    # Scale initial solution
    x0 *= n // g
    y0 *= n // g

    # Fix signs depending on a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b//g)
    # y = y0 - k*(a//g)
    # We want to find k such that x >= 0 and minimal non-negative x starting from 0 upwards.

    step_x = b // g
    step_y = a // g

    # If step_x == 0, then a solution x is fixed; just check if x0 >= 0
    if step_x == 0:
        if x0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return 'No solution'

    # Find minimal k such that x0 + k*step_x >= 0
    # k >= (-x0)/step_x
    # Because step_x can be positive or negative, handle accordingly.

    if step_x > 0:
        k_min = (-x0 + step_x - 1) // step_x  # Ceiling division
    else:
        # step_x < 0
        k_min = (-x0) // step_x  # floor division because step_x negative

    # Try k = k_min, k_min+1, ... until we find first x >= 0
    # But k_min is the minimal k giving x >= 0, so check that only.

    x_candidate = x0 + k_min * step_x
    y_candidate = y0 - k_min * step_y
    if x_candidate >= 0:
        return ('x = ', x_candidate, ', y = ', y_candidate)

    # If not, try next k upwards (+1)
    x_candidate = x0 + (k_min + 1) * step_x
    y_candidate = y0 - (k_min + 1) * step_y
    if x_candidate >= 0:
        return ('x = ', x_candidate, ', y = ', y_candidate)

    # If no positive x found (should be rare), return No solution
    return 'No solution'

