def decode_list(encoded):
    result = []
    for item in encoded:
        # Check if item is a list or tuple of length 2
        if isinstance(item, (list, tuple)) and len(item) == 2:
            count, value = item
            # Validate count
            if not isinstance(count, int) or count < 0:
                raise ValueError(f"Invalid count {count}: must be a non-negative integer")
            result.extend([value] * count)
        else:
            # Any other element is treated as a single literal value
            result.append(item)
    return result

