def get_total_number_of_sequences(m, n):
    # dp[i][x] = number of sequences of length i ending with element x
    # i ranges from 1 to n
    # x ranges from 1 to m

    if n == 1:
        # Any element from 1 to m can be the sequence
        return m

    dp = [ [0] * (m + 1) for _ in range(n + 1) ]

    # Base case: sequences of length 1
    for x in range(1, m + 1):
        dp[1][x] = 1

    for length in range(2, n + 1):
        # For each possible current element x,
        # sum over all previous elements y where x >= 2*y
        for x in range(1, m + 1):
            total = 0
            # y must satisfy y <= x//2 because x >= 2*y
            max_prev = x // 2
            for y in range(1, max_prev + 1):
                total += dp[length - 1][y]
            dp[length][x] = total

    # total sequences of length n is sum over all ending elements x
    return sum(dp[n][1:])

