def even_binomial_Coeff_Sum(n: int) -> int:
    # Using the known identity:
    # sum_{k even} C(n, k) = 2^(n-1) + (1 + (-1)^n)/2 * C(n, n/2)
    # But simpler and more direct is:
    # sum_{k even} C(n, k) = 2^(n-1) + (1/2)*C(n, n/2) if n even,
    # or sum_{k even} C(n, k) = 2^(n-1) if n odd (because middle term is odd index).
    # However, the simplest and always correct approach is:
    # sum_{k even} C(n, k) = 2^(n-1) + (1/2)*C(n, n/2) if n even,
    # else 2^(n-1)
    #
    # But the problem only requires sum of even-index binomial coefficients,
    # so the standard formula is:
