def flatten_list(nested):
    """
    Recursively flatten a nested collection composed of lists, tuples, and sets
    into a flat list.

    For lists and tuples, preserve order.
    For sets, order can be arbitrary.

    Args:
        nested (list|tuple|set|any): nested collection of lists, tuples, or sets or an element.

    Returns:
        list: flat list of all elements.
    """
    if isinstance(nested, list):
        result = []
        for item in nested:
            result.extend(flatten_list(item))
        return result
    elif isinstance(nested, tuple):
        result = []
        for item in nested:
            result.extend(flatten_list(item))
        return result
    elif isinstance(nested, set):
        result = []
        for item in nested:
            result.extend(flatten_list(item))
        return result
    else:
        return [nested]

