def smallest_missing(nums):
    """
    Given a sorted list of integers, find the smallest missing integer assuming
    the expected value at each index is equal to the index itself.

    If the list is empty, return 0.

    Examples:
    smallest_missing([]) -> 0
    smallest_missing([0, 1, 2, 6, 9]) -> 3 (since index 3 expected 3 but got 6)
    smallest_missing([0, 1, 2, 3]) -> 4 (no missing, so return max + 1)
    smallest_missing([1, 2, 3]) -> 0 (index 0 expected 0 but got 1)
    """
    if not nums:
        return 0

    for i, v in enumerate(nums):
        if v != i:
