def permute_string(s: str) -> list[str]:
    """
    Generate all unique permutations of the input string s,
    including duplicates if present in the input,
    in the specific order defined by:
      - Recursively permute the suffix (all chars except first)
      - Insert the first character into each position from left to right in each suffix permutation

    For example:
    permute_string('abc') returns:
    ['abc', 'bac', 'bca', 'acb', 'cab', 'cba']
    """
    if len(s) <= 1:
        return [s]

    first_char = s[0]
    suffix_perms = permute_string(s[1:])
    result = []

    for perm in suffix_perms:
        # Insert first_char into every position of perm, left to right
        for i in range(len(perm) + 1):
            new_perm = perm[:i] + first_char + perm[i:]
            result.append(new_perm)

    return result

