def find_Max(arr, low, high):
    """
    Find the maximum element in a rotated sorted array within the subrange [low, high].

    Parameters:
    arr (list): The list of comparable elements, originally sorted ascending then rotated.
    low (int): The start index of the subrange to search.
    high (int): The end index of the subrange to search.

    Returns:
    The maximum element in arr[low..high], or None if the range is empty or invalid.
    """
    if low > high or low < 0 or high >= len(arr):
        return None
    if low == high:
        return arr[low]

    # If subarray is already sorted (no rotation), the max is the rightmost element
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2
        # Check if mid is pivot (max) - element greater than next element
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # Check if mid-1 is pivot (max)
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to go
        if arr[mid] >= arr[low]:
            # Left part is sorted, max in right part
            low = mid + 1
        else:
            # Max in left part
            high = mid - 1

    # If we exit loop, the maximum is at low (should not happen in rotated sorted array)
    return arr[low]
