def reverse_Array_Upto_K(arr, k):
    """
    Returns a new list where the first k elements are reversed,
    and the rest of the elements remain unchanged.
    k is clamped to [0, len(arr)] (exclusive end index).

    Parameters:
    arr (list): input list to reorder
    k (int): exclusive end index up to which to reverse elements

    Returns:
    list: new list with first k elements reversed, rest unchanged
    """
    n = len(arr)
    k = max(0, min(k, n))  # Clamp k to [0, n]
    return arr[:k][::-1] + arr[k:]
