def check_subset(coll1, coll2):
    """
    Returns True if every unique element in coll2 appears at least once in coll1,
    ignoring element counts. Otherwise, returns False.

    Args:
        coll1: An iterable of hashable elements.
        coll2: An iterable of hashable elements.

    Returns:
        bool: True if unique elements of coll2 are subset of unique elements of coll1.
    """
    set1 = set(coll1)
    set2 = set(coll2)
    return set2.issubset(set1)

