def filter_data(data):
    """
    Filters a dictionary of person measurements, keeping only entries where the
    value is a 2-item indexable sequence (like a tuple) and both items are numeric (int or float).

    Args:
        data (dict): Dictionary with person identifiers as keys and measurements as values.
                     Each value should be a 2-item sequence (e.g., tuple) representing measurements.

    Returns:
        dict: A dictionary containing only entries with 2-item sequences whose both elements
              are numeric (int or float), preserving original keys and values.
    """
    def is_numeric(x):
        return isinstance(x, (int, float))

    filtered = {}
    for key, value in data.items():
        # Check if value is indexable, has length 2, and both elements are numeric
        if (
            hasattr(value, '__getitem__')
            and hasattr(value, '__len__')
            and len(value) == 2
            and is_numeric(value[0])
