import re

def capital_words_spaces(text: str) -> str:
    """
    Insert spaces before uppercase letters that are immediately preceded by a word character,
    effectively splitting words at those points.

    Args:
        text (str): Input text.

    Returns:
        str: Modified text with spaces inserted before uppercase letters as described.
    """
    # Pattern: match uppercase letter preceded by a word character (letter/digit/underscore)
    # Replace with a space and that uppercase letter
    return re.sub(r'(?<=\w)([A-Z])', r' \1', text)

