def count_list(collections):
    """
    Count how many immediate elements are inside the input collection, regardless of their type.

    Raises an error if the input is not a collection type.

    For dicts, counts the total number of keys and values (each counts as one element).

    Args:
        collections: A collection (list, tuple, set, dict, etc.).

    Returns:
        int: Number of immediate elements inside the input collection.

    Raises:
        TypeError: If input is not a collection type.
    """
    # Check if input is a collection type
    # Accept types that are iterable and have __len__, but exclude strings and bytes
    if isinstance(collections, (str, bytes)):
        raise TypeError(f"Input of type {type(collections).__name__} is not considered a collection for this function.")

    try:
        # Try to get the length of the input
        length = len(collections)
    except TypeError:
        raise TypeError(f"Input of type {type(collections).__name__} is not a collection.")

    # For dict, count keys and values separately as immediate elements
    if isinstance(collections, dict):
        return len(collections) * 2  # keys + values

    # For other collections, just return their length
    return length

