def check_Even_Parity(value):
    if not isinstance(value, int):
        raise TypeError("Input must be an integer")

    if value == 0:
        # zero has zero 1 bits, which is even
        return True

    if value > 0:
        # count bits set in straightforward binary representation
        count_ones = bin(value).count('1')
    else:
        # For negative numbers, compute minimal two's complement bit width
        # Find minimal number of bits n such that -2^(n-1) <= value < 2^(n-1)
        # Then mask value with n bits and count ones
        abs_val = abs(value)
        # minimal bits needed to represent abs_val is abs_val.bit_length()
        # We try increasing n starting from abs_val.bit_length()+1 (to cover sign bit)
        n = abs_val.bit_length() + 1
        # Check if value fits in n bits two's complement
        # range: -2^(n-1) <= value < 2^(n-1)
        # if value < -2**(n-1), increase n by 1 until it fits
        while value < -2**(n-1):
            n += 1
        # mask value to n bits two's complement
        mask = (1 << n) - 1
        twos_comp = value & mask
        count_ones = bin(twos_comp).count('1')

    return (count_ones % 2) == 0
check_even_parity = check_Even_Parity

