def zip_tuples(t1, t2):
    """
    Pairs each element of the first tuple with elements of the second tuple in a cycling pattern,
    so the output length matches the length of the first tuple.

    Args:
        t1 (tuple): The first tuple.
        t2 (tuple): The second tuple.

    Returns:
        tuple: A tuple of pairs where each element of t1 is paired with an element from t2 cycling through t2.
    """
    if not t2:
        raise ValueError("Second tuple must not be empty to cycle through its elements.")

    return tuple((t1[i], t2[i % len(t2)]) for i in range(len(t1)))

