def next_smallest_palindrome(num: int) -> int:
    # Treat negative inputs as zero
    if num < 0:
        num = 0

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    candidate = num + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1

