def find_solution(a: int, b: int, n: int):
    # Scan non-negative x from 0 upwards
    x = 0
    while True:
        remainder = n - a * x
        # Check if remainder is divisible by b
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        # If b == 0, then equation is a*x = n, so y can be anything
        elif b == 0:
            # Then a * x = n must hold
            if a != 0 and n % a == 0:
                x_candidate = n // a
                if x_candidate >= 0:
                    # y can be any integer, choose y=0
                    return (x_candidate, 0)
            return 'No solution'
        # To avoid infinite loop, if a > 0 and a*x > n and b > 0, no solution
        # or if a < 0 and x grows positively, a*x goes negative, but n may be positive
        # Let's set a reasonable upper bound for x scanning:
        # Since x must be non-negative, and we want smallest x,
        # If a > 0 and a*x > n, further increases won't help; stop.
        if a > 0 and a * x > n:
            break
        # Similarly, if a == 0, equation is b*y = n, x=0 fixed
        if a == 0:
            if b != 0 and n % b == 0:
                y = n // b
                if y >= 0:
                    return (0, y)
            break
        x += 1
    return 'No solution'

