def decode_list(encoded):
    """
    Decodes a run-length encoded list with mixed input:
    - Elements that are lists or tuples of length 2 are treated as [count, value].
    - Other elements are treated as literal values appearing once.

    Args:
        encoded (list): List of elements, each either a single value or a pair [count, value].

    Returns:
        list: Decoded list with values repeated according to counts.
    """
    decoded = []
    for item in encoded:
        if isinstance(item, (list, tuple)) and len(item) == 2:
            count, value = item
            # Count is non-negative integer, repeat value count times
            decoded.extend([value] * count)
        else:
            # Literal value appearing once
            decoded.append(item)
    return decoded

