def get_total_number_of_sequences(m, n):
    # m: maximum element value (>=1)
    # n: sequence length (>=0)
    # Count sequences length n, elements in [1..m], each next element >= 2 * previous element

    if n == 0:
        # By convention, one empty sequence
        return 1
    if n == 1:
        # Any single element in [1..m]
        return m

    # dp[i][x]: number of sequences of length i ending with element x
    # i from 1 to n, x from 1 to m
    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1

    for i in range(2, n+1):
        # For each possible current element x,
        # sum dp[i-1][prev] for prev where x >= 2*prev
        # i.e. prev <= x//2
        prefix_sum = 0
        # To optimize summation, precompute prefix sums of dp[i-1]
        prefix = [0]*(m+1)
        for val in range(1, m+1):
            prefix[val] = prefix[val-1] + dp[i-1][val]

        for x in range(1, m+1):
            max_prev = x // 2
            if max_prev >= 1:
                dp[i][x] = prefix[max_prev]
            else:
                dp[i][x] = 0

    return sum(dp[n][1:])

