def diff_consecutivenums(nums):
    """
    Compute and return a list of differences between consecutive numbers in the input list.
    Each difference is computed as nums[i+1] - nums[i].
    If the input list has fewer than two elements, return an empty list.

    Parameters:
    nums (list-like): A list or sequence of numbers supporting indexing and len()

    Returns:
    list: List of differences between consecutive numbers
    """
    if len(nums) < 2:
        return []
    return [nums[i+1] - nums[i] for i in range(len(nums) - 1)]

