def smallest_missing(arr):
    """
    Find the smallest missing non-negative integer starting from 0 in a sorted array.

    Args:
        arr (List[int]): Sorted list of integers in ascending order (possibly empty).

    Returns:
        int: The smallest missing non-negative integer.
    """
    # Initialize the smallest missing integer to 0
    missing = 0

    for num in arr:
        if num == missing:
            missing += 1
        elif num > missing:
            # Since arr is sorted, missing is not in arr and is the smallest missing
            break
        # If num < missing, continue, since duplicates or smaller values don't affect missing

    return missing

