def permute_string(s):
    """
    Generate and return a list of unique permutations of the input string s,
    including duplicates in the input string.

    :param s: input string
    :return: list of unique permutation strings
    """
    def backtrack(path, used):
        if len(path) == len(s):
            permutations.append("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    permutations = []
    used = [False] * len(s)
    backtrack([], used)
    # Remove duplicates by converting to set, then back to list
    # and sort for consistent order
    unique_permutations = sorted(set(permutations))
    return unique_permutations

