def find_Max(nums):
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    # If the array is not rotated (strictly ascending), the last element is the max
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2

        # If mid element is greater than the rightmost element,
        # maximum is in the right half (including mid)
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            # Maximum is in the left half (excluding mid)
            right = mid

    # After loop, left points to the smallest element (pivot),
    # so maximum is element before it
    return nums[left - 1]
find_max = find_Max

