from collections import Counter

def check_subset(t1, t2):
    """
    Returns True if every element in t2 appears in t1 at least as many times as it appears in t2.
    In other words, t2 is a multiset subset of t1.
    """
    c1 = Counter(t1)
    c2 = Counter(t2)
    for elem, count in c2.items():
        if c1[elem] < count:
