def filter_data(data, min_height=0, max_height=float('inf'), min_width=0, max_width=float('inf')):
    """
    Filters students based on height and width thresholds.

    Parameters:
        data (dict): Mapping from student identifier to a tuple or list of exactly two values (height, width).
        min_height (int or float): Minimum height threshold (inclusive).
        max_height (int or float): Maximum height threshold (inclusive).
        min_width (int or float): Minimum width threshold (inclusive).
        max_width (int or float): Maximum width threshold (inclusive).

    Returns:
        dict: Filtered dictionary containing only students whose height and width are within the given thresholds.
    """
