def check_Even_Parity(num: int) -> bool:
    """
    Returns True if the number of set bits (1s) in the binary representation
    of num is even, otherwise False.

    Examples:
    check_Even_Parity(0) -> True  (binary 0 has 0 set bits, which is even)
    check_Even_Parity(5) -> False (binary 101 has 2 set bits, which is even, so True)
    check_Even_Parity(7) -> False (binary 111 has 3 set bits, which is odd)
    """
    count_ones = bin(num).count('1')
    return (count_ones % 2) == 0
