def substract_elements(a, b):
    """
    Subtract elements of two nested tuples (or integers) of equal structure element-wise.
    Returns a nested tuple of the same shape with the element-wise differences.

    Args:
        a (int or tuple): First nested tuple or integer.
        b (int or tuple): Second nested tuple or integer.

    Returns:
        int or tuple: Nested tuple or int with element-wise subtraction results.
    """
    if isinstance(a, int) and isinstance(b, int):
        return a - b
    elif isinstance(a, tuple) and isinstance(b, tuple):
        if len(a) != len(b):
            raise ValueError("Input tuples must have the same structure and length")
        return tuple(substract_elements(x, y) for x, y in zip(a, b))
    else:
        # Different types or structure mismatch
        raise TypeError("Both inputs must be integers or tuples of the same structure")

