def lucky_num(n):
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))  # Generate a sufficiently large list to ensure n lucky numbers
    idx = 1  # start with the second element (index 1), which is the first step (k)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # We keep the numbers that are not at positions multiple of step
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
        if len(numbers) >= n:
            # If we already have enough lucky numbers, we can break early
