def get_noOfways(n: int) -> int:
    """
    Compute the number of ways to tile a 2 x n board using 2 x 1 domino tiles.

    Args:
        n (int): The length of the board.

    Returns:
        int: The number of distinct tilings of the 2 x n board.
             Returns 0 if n is negative.
    """
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1

    # dp[i] = number of ways to tile 2 x i board
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1

    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[n]
